window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["geo-map-extract"]={"pkg":{"id":"geo-map-extract","sceneId":"g3","methods":["cv","nlp"],"title":"历史地质图件要素检测、OCR与拓扑矢量化","version":"1.0.0","updated":"2026-11-01","tabs":{"background":{"label":"专业背景","lede":"油气田档案馆保存着数以万计上世纪 50–90 年代测绘的纸质与晒印地质图，里面记录了不可复现的地表露头产状、断层迹线与老探井位置。但这些历史图件目前大多只是一张张「死图片」（扫描栅格 TIFF）——无法在三维地质建模或 GIS 系统里按地层查询或做空间叠合分析。人工在 GIS 软件里逐幅描线、查图例录代号、检查多边形拓扑闭合，一幅 1:50,000 图件就要耗费 **1.5–2 人·天**。","judge":[{"label":"数据形态","value":"历史扫描地质图","desc":"300dpi+ 栅格图件（含主图、图例与剖面）"},{"label":"核心卡点","value":"字压线断口与褪色","desc":"注记压断断层线导致多边形无法闭合"},{"label":"可见收益","value":"1.8天 ➔ 25分钟/幅","desc":"省去 90% 人工描线与查图例录属性时间"},{"label":"难度","value":"中","desc":"需结合视觉检测、上下标OCR与拓扑重建"}],"sections":[{"no":1,"en":"","title":"当前做法与问题","html":"<p>区域地质图与构造纲要图是油气勘探最基础的「底图」。一幅标准的 1:50,000 历史地质图包含五个紧密咬合的结构组件：<b>① 主图区</b>（成百上千个地层色块、断层线、产状符号 <code>┣ 32°</code>、老探井符号 <code>⊕</code>）、<b>② 图例栏</b>（定义本图每种色彩/岩性花纹对应的地层代号与年代）、<b>③ 地质剖面图</b>、<b>④ 综合地层柱状图</b>以及<b>⑤ 图廓坐标与责任表</b>。</p><div class=\"figure\"><svg viewBox=\"0 0 760 310\" width=\"100%\" role=\"img\" aria-label=\"典型历史扫描地质图的版面解剖与五类待提取要素\">\n  <defs>\n    <pattern id=\"gme-pat-brick\" width=\"16\" height=\"10\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"16\" height=\"10\" fill=\"#d9c7a3\"/>\n      <path d=\"M0,5 H16 M8,0 V5 M0,5 V10\" stroke=\"#7d6b52\" stroke-width=\"0.7\" fill=\"none\"/>\n    </pattern>\n    <pattern id=\"gme-pat-dots\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"12\" height=\"12\" fill=\"#e4d6b8\"/>\n      <circle cx=\"3\" cy=\"3\" r=\"1\" fill=\"#7d6b52\"/><circle cx=\"9\" cy=\"9\" r=\"1\" fill=\"#7d6b52\"/>\n    </pattern>\n    <pattern id=\"gme-pat-slash\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"12\" height=\"12\" fill=\"#c7d0be\"/>\n      <path d=\"M-2,12 L12,-2\" stroke=\"#5b6954\" stroke-width=\"0.7\"/>\n    </pattern>\n    <radialGradient id=\"gme-stain\" cx=\"45%\" cy=\"48%\" r=\"52%\">\n      <stop offset=\"0%\" stop-color=\"#c27a2c\" stop-opacity=\"0.22\"/>\n      <stop offset=\"70%\" stop-color=\"#c27a2c\" stop-opacity=\"0.08\"/>\n      <stop offset=\"100%\" stop-color=\"#c27a2c\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <rect width=\"760\" height=\"310\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- 左侧：微缩历史地质图幅 -->\n  <g transform=\"translate(16,14)\">\n    <rect x=\"0\" y=\"0\" width=\"470\" height=\"282\" rx=\"4\" fill=\"#f4ebd6\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n    <rect x=\"6\" y=\"6\" width=\"458\" height=\"270\" fill=\"none\" stroke=\"#737c83\" stroke-width=\"0.7\" stroke-dasharray=\"4 2\"/>\n    <!-- ⑤ 图名与责任表 -->\n    <text x=\"165\" y=\"21\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\">四川省川东华蓥山幅 1:50,000 地质图 (1978年晒印)</text>\n    <rect x=\"330\" y=\"242\" width=\"128\" height=\"28\" fill=\"#fbf7ec\" stroke=\"#737c83\" stroke-width=\"0.8\"/>\n    <text x=\"394\" y=\"254\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#424a50\">⑤ 四川省地质局第二区测队</text>\n    <text x=\"394\" y=\"264\" text-anchor=\"middle\" font-size=\"8\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">高斯-克吕格 1954北京坐标系</text>\n\n    <!-- ① 主图区 -->\n    <g transform=\"translate(14,28)\">\n      <rect x=\"0\" y=\"0\" width=\"304\" height=\"154\" fill=\"#e4d6b8\" stroke=\"#12615a\" stroke-width=\"1.6\"/>\n      <polygon points=\"0,0 118,0 92,154 0,154\" fill=\"url(#gme-pat-brick)\"/>\n      <polygon points=\"118,0 218,0 188,154 92,154\" fill=\"url(#gme-pat-dots)\"/>\n      <polygon points=\"218,0 304,0 304,154 188,154\" fill=\"url(#gme-pat-slash)\"/>\n      <!-- 泛黄底噪与折痕 -->\n      <rect x=\"0\" y=\"0\" width=\"304\" height=\"154\" fill=\"url(#gme-stain)\"/>\n      <path d=\"M0,98 L160,106 L304,118\" stroke=\"#faf5e8\" stroke-width=\"3.2\" fill=\"none\"/>\n      <path d=\"M0,99 L160,107 L304,119\" stroke=\"#a67c46\" stroke-width=\"0.8\" stroke-dasharray=\"3 2\" fill=\"none\"/>\n      <!-- 断层线 F1 & F2 (含文字压盖断口) -->\n      <path d=\"M118,0 L106,58 M102,78 L92,154\" stroke=\"#b4483c\" stroke-width=\"2\" fill=\"none\"/>\n      <polygon points=\"111,28 117,31 110,34\" fill=\"#b4483c\"/>\n      <polygon points=\"97,118 103,121 96,124\" fill=\"#b4483c\"/>\n      <path d=\"M218,0 L199,96 M195,114 L188,154\" stroke=\"#b4483c\" stroke-width=\"1.8\" fill=\"none\"/>\n      <!-- 压盖断层的地层代号与断线红圈告警 -->\n      <circle cx=\"104\" cy=\"68\" r=\"11\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"1.3\" stroke-dasharray=\"2 2\"/>\n      <text x=\"104\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">P₁m</text>\n      <text x=\"155\" y=\"54\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₃x</text>\n      <text x=\"255\" y=\"62\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">J₂s</text>\n      <!-- 产状符号 ┣ 32° -->\n      <g transform=\"translate(52,48) rotate(-22)\">\n        <line x1=\"-8\" y1=\"0\" x2=\"8\" y2=\"0\" stroke=\"#15191c\" stroke-width=\"1.6\"/>\n        <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"5.5\" stroke=\"#15191c\" stroke-width=\"1.6\"/>\n      </g>\n      <text x=\"61\" y=\"52\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">32°</text>\n      <!-- 钻孔符号 ⊕ ZK-04 -->\n      <circle cx=\"164\" cy=\"122\" r=\"5\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.4\"/>\n      <path d=\"M158,122 H170 M164,116 V128\" stroke=\"#3a6ea5\" stroke-width=\"1.2\"/>\n      <text x=\"172\" y=\"125\" font-size=\"9\" font-weight=\"700\" fill=\"#3a6ea5\" font-family=\"ui-monospace,Consolas,monospace\">ZK-04</text>\n      <!-- 区域角标 -->\n      <rect x=\"4\" y=\"4\" width=\"66\" height=\"16\" rx=\"3\" fill=\"#12615a\"/>\n      <text x=\"37\" y=\"15\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">① 主图区</text>\n    </g>\n\n    <!-- ② 图例栏 -->\n    <g transform=\"translate(328,28)\">\n      <rect x=\"0\" y=\"0\" width=\"130\" height=\"128\" fill=\"#fbf8f1\" stroke=\"#c27a2c\" stroke-width=\"1.5\"/>\n      <rect x=\"4\" y=\"4\" width=\"66\" height=\"15\" rx=\"3\" fill=\"#c27a2c\"/>\n      <text x=\"37\" y=\"14.5\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#fff\">② 图例栏</text>\n      <rect x=\"8\" y=\"25\" width=\"24\" height=\"14\" fill=\"url(#gme-pat-brick)\" stroke=\"#424a50\" stroke-width=\"0.7\"/>\n      <text x=\"37\" y=\"35\" font-size=\"9\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">P₁m 茅口组灰岩</text>\n      <rect x=\"8\" y=\"45\" width=\"24\" height=\"14\" fill=\"url(#gme-pat-dots)\" stroke=\"#424a50\" stroke-width=\"0.7\"/>\n      <text x=\"37\" y=\"55\" font-size=\"9\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₃xj 须家河砂岩</text>\n      <rect x=\"8\" y=\"65\" width=\"24\" height=\"14\" fill=\"url(#gme-pat-slash)\" stroke=\"#424a50\" stroke-width=\"0.7\"/>\n      <text x=\"37\" y=\"75\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\">J₂sh ≠ 现标 J₂s</text>\n      <text x=\"8\" y=\"96\" font-size=\"8.5\" fill=\"#424a50\">▲ 逆冲断层   ┣ 产状</text>\n      <text x=\"8\" y=\"112\" font-size=\"8.5\" fill=\"#737c83\">⊕ 钻孔位置   — 整合界线</text>\n    </g>\n\n    <!-- ④ 综合地层柱状图 -->\n    <g transform=\"translate(328,162)\">\n      <rect x=\"0\" y=\"0\" width=\"130\" height=\"74\" fill=\"#fbf8f1\" stroke=\"#6b5aa6\" stroke-width=\"1.3\"/>\n      <rect x=\"4\" y=\"4\" width=\"94\" height=\"15\" rx=\"3\" fill=\"#6b5aa6\"/>\n      <text x=\"51\" y=\"14.5\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#fff\">④ 综合地层柱状图</text>\n      <rect x=\"8\" y=\"23\" width=\"22\" height=\"44\" fill=\"url(#gme-pat-brick)\" stroke=\"#424a50\" stroke-width=\"0.7\"/>\n      <line x1=\"8\" y1=\"38\" x2=\"30\" y2=\"38\" stroke=\"#424a50\"/><line x1=\"8\" y1=\"52\" x2=\"30\" y2=\"52\" stroke=\"#424a50\"/>\n      <text x=\"36\" y=\"34\" font-size=\"8.5\" fill=\"#424a50\">J₂s 厚 420m 紫红泥岩</text>\n      <text x=\"36\" y=\"48\" font-size=\"8.5\" fill=\"#424a50\">T₃x 厚 580m 含煤砂岩</text>\n      <text x=\"36\" y=\"62\" font-size=\"8.5\" fill=\"#424a50\">P₁m 厚 310m 生物灰岩</text>\n    </g>\n\n    <!-- ③ 地质剖面图 A-A' -->\n    <g transform=\"translate(14,190)\">\n      <rect x=\"0\" y=\"0\" width=\"304\" height=\"80\" fill=\"#fbf8f1\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n      <rect x=\"4\" y=\"4\" width=\"96\" height=\"15\" rx=\"3\" fill=\"#3a6ea5\"/>\n      <text x=\"52\" y=\"14.5\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#fff\">③ 地质剖面图 A–A'</text>\n      <path d=\"M10,42 Q85,18 160,38 T294,35 L294,72 L10,72 Z\" fill=\"#e4d6b8\" stroke=\"#424a50\" stroke-width=\"1\"/>\n      <path d=\"M10,55 Q85,32 160,52 T294,50\" stroke=\"#7d6b52\" stroke-width=\"1\" fill=\"none\"/>\n      <line x1=\"115\" y1=\"24\" x2=\"96\" y2=\"72\" stroke=\"#b4483c\" stroke-width=\"1.8\"/>\n      <line x1=\"210\" y1=\"32\" x2=\"195\" y2=\"72\" stroke=\"#b4483c\" stroke-width=\"1.6\"/>\n    </g>\n  </g>\n\n  <!-- 右侧：五类要素与三大扫描退化痛点解析 -->\n  <g transform=\"translate(500,14)\">\n    <rect x=\"0\" y=\"0\" width=\"244\" height=\"282\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"22\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">五类待提取要素与扫描退化干扰</text>\n    <line x1=\"12\" y1=\"30\" x2=\"232\" y2=\"30\" stroke=\"#e7e3da\"/>\n\n    <g transform=\"translate(12,42)\" font-size=\"10.5\" fill=\"#424a50\">\n      <circle cx=\"6\" cy=\"5\" r=\"5\" fill=\"#12615a\"/><text x=\"16\" y=\"9\" font-weight=\"700\" fill=\"#15191c\">面要素：地层色块与岩性花纹</text>\n      <text x=\"16\" y=\"24\" font-size=\"9.5\" fill=\"#737c83\">依赖边界完全闭合；晒印褪色导致同层异色</text>\n\n      <circle cx=\"6\" cy=\"43\" r=\"5\" fill=\"#b4483c\"/><text x=\"16\" y=\"47\" font-weight=\"700\" fill=\"#15191c\">线要素：断层线与不整合界线</text>\n      <text x=\"16\" y=\"62\" font-size=\"9.5\" fill=\"#737c83\">含逆冲三角齿/正断层短线，极易被文字压断</text>\n\n      <circle cx=\"6\" cy=\"81\" r=\"5\" fill=\"#2f7d5b\"/><text x=\"16\" y=\"85\" font-weight=\"700\" fill=\"#15191c\">点符号：产状 (┣ 32°) 与钻孔 (⊕)</text>\n      <text x=\"16\" y=\"100\" font-size=\"9.5\" fill=\"#737c83\">需同时回归长短线旋转角并关联旁侧倾角数字</text>\n\n      <circle cx=\"6\" cy=\"119\" r=\"5\" fill=\"#c27a2c\"/><text x=\"16\" y=\"123\" font-weight=\"700\" fill=\"#15191c\">跨年代图例编码：J₂s vs J₂sh</text>\n      <text x=\"16\" y=\"138\" font-size=\"9.5\" fill=\"#737c83\">50年代—90年代图件代号各异，需本图图例自对齐</text>\n    </g>\n\n    <rect x=\"12\" y=\"196\" width=\"220\" height=\"74\" rx=\"5\" fill=\"#f6e3df\" stroke=\"#b4483c\" stroke-width=\"0.8\"/>\n    <text x=\"20\" y=\"213\" font-size=\"10.5\" font-weight=\"700\" fill=\"#b4483c\">三大典型图纸扫描退化伪影：</text>\n    <text x=\"20\" y=\"230\" font-size=\"9.5\" fill=\"#424a50\">1. 注记压盖断层：代号 P₁m 直接印在断层线上</text>\n    <text x=\"20\" y=\"245\" font-size=\"9.5\" fill=\"#424a50\">2. 物理折痕断线：十字折痕造成 15–25px 空白带</text>\n    <text x=\"20\" y=\"260\" font-size=\"9.5\" fill=\"#424a50\">3. 纸张泛黄褐斑：降低上下标小字与浅色界线对比度</text>\n  </g>\n</svg></div><div class=\"figcap\"><b>图 1</b><span>一幅典型历史扫描地质图的版面结构（①主图区、②图例栏、③剖面图、④柱状图、⑤责任表）及文字压盖断层、折痕断线等核心痛点。</span></div><p>要把这样一张扫描栅格图变成 GIS 可查询的矢量图层（Shapefile / GeoJSON），目前普遍依赖作业员在 ArcGIS 或 MapGIS 中<b>纯手工数字化</b>：先放大底图沿着断层和地层界线逐点鼠标描线（占 45% 工时），再对照右侧图例栏逐个多边形录入地层代号、倾角和井号（占 30% 工时），最后运行拓扑检查修补未闭合的悬挂线（占 25% 工时）。传统基于颜色阈值的自动追踪工具在历史地质图上几乎全军覆没，原因在于两大行业痛点：一是制图规范采用<b>「字压线让位」</b>（地层代号直接印在界线或断层上，把线条切成数段）加上纸张十字折痕，造成成百上千个<b>拓扑悬挂断口（Dangles）</b>；二是<b>跨年代地层编码演进</b>（如 1970 年代写作 <code>J₂sh</code> 沙溪庙系，现行国标写作 <code>J₂s</code> 沙溪庙组），通用 OCR 既认不出上下标，也无法对齐历史术语。</p><div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"人工GIS矢量化耗时拆解与断线痛点\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"20\" y=\"26\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">单幅 1:50,000 地质图人工 GIS 矢量化耗时拆解（平均 1.5–2.0 人·天 / 幅，约 3,000–5,000 个多边形与符号）</text>\n  <!-- 耗时分段条 -->\n  <g transform=\"translate(20,38)\">\n    <rect x=\"0\" y=\"0\" width=\"324\" height=\"32\" rx=\"4\" fill=\"#12615a\"/>\n    <text x=\"162\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\">人工逐点描线（界线+断层） 45% (约 6.5 小时)</text>\n    <rect x=\"328\" y=\"0\" width=\"214\" height=\"32\" rx=\"4\" fill=\"#c27a2c\"/>\n    <text x=\"435\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\">查图例录代号与产状 30% (4.5 小时)</text>\n    <rect x=\"546\" y=\"0\" width=\"174\" height=\"32\" rx=\"4\" fill=\"#b4483c\"/>\n    <text x=\"633\" y=\"20\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\">拓扑查错与缝合 25% (3.5h)</text>\n  </g>\n\n  <!-- 下半部：两个核心卡点微观放大 -->\n  <g transform=\"translate(20,84)\">\n    <rect x=\"0\" y=\"0\" width=\"352\" height=\"120\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11\" font-weight=\"700\" fill=\"#b4483c\">卡点 A：注记压盖与折痕导致自动二值化线条断裂</text>\n    <!-- 放大示意 -->\n    <rect x=\"14\" y=\"30\" width=\"145\" height=\"76\" rx=\"4\" fill=\"#f4ebd6\" stroke=\"#d9d4c8\"/>\n    <line x1=\"26\" y1=\"96\" x2=\"66\" y2=\"66\" stroke=\"#b4483c\" stroke-width=\"2.5\"/>\n    <line x1=\"102\" y1=\"42\" x2=\"144\" y2=\"14\" stroke=\"#b4483c\" stroke-width=\"2.5\"/>\n    <circle cx=\"66\" cy=\"66\" r=\"3.5\" fill=\"#b4483c\"/><circle cx=\"102\" cy=\"42\" r=\"3.5\" fill=\"#b4483c\"/>\n    <rect x=\"64\" y=\"44\" width=\"38\" height=\"20\" fill=\"#f4ebd6\" stroke=\"#b4483c\" stroke-dasharray=\"2 2\"/>\n    <text x=\"83\" y=\"58\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₃x</text>\n    <text x=\"170\" y=\"48\" font-size=\"10\" fill=\"#424a50\">• 制图规范要求「字压线让位」，扫描后</text>\n    <text x=\"170\" y=\"64\" font-size=\"10\" fill=\"#424a50\">  界线在注记处出现 15–25 px 物理空白；</text>\n    <text x=\"170\" y=\"80\" font-size=\"10\" fill=\"#424a50\">• 产生两个<tspan fill=\"#b4483c\" font-weight=\"700\">悬挂端点 (Dangles)</tspan>，导致</text>\n    <text x=\"170\" y=\"96\" font-size=\"10\" fill=\"#424a50\">  左右两侧地层多边形泄露融合、无法造面。</text>\n  </g>\n\n  <g transform=\"translate(388,84)\">\n    <rect x=\"0\" y=\"0\" width=\"352\" height=\"120\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11\" font-weight=\"700\" fill=\"#c27a2c\">卡点 B：跨年代岩石地层代号演进与上下标易混</text>\n    <rect x=\"14\" y=\"30\" width=\"324\" height=\"76\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n    <text x=\"24\" y=\"50\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">1965年图件：<tspan fill=\"#c27a2c\" font-weight=\"700\">J₂sh</tspan> (沙溪庙系)  ──► 现行国标：<tspan fill=\"#12615a\" font-weight=\"700\">J₂s</tspan> (沙溪庙组)</text>\n    <text x=\"24\" y=\"70\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">1978年图件：<tspan fill=\"#c27a2c\" font-weight=\"700\">T₃xj</tspan> (须家河统) ──► 现行国标：<tspan fill=\"#12615a\" font-weight=\"700\">T₃x</tspan> (须家河组)</text>\n    <text x=\"24\" y=\"92\" font-size=\"10\" fill=\"#737c83\">通用 OCR 易将下标「₁/₂/₃」误识为「l/z/s」，且无法关联跨年代旧地层名。</text>\n  </g>\n</svg></div><div class=\"figcap\"><b>图 2</b><span>人工矢量化耗时分布及传统自动矢量化工具面临的「文字压盖断线」与「跨年代地层代号演进」两大核心痛点。</span></div>"},{"no":2,"en":"","title":"AI 能做什么","html":"<p>现代智能化的解决之道不是用单一模型「硬端到端」，而是构造一条<b>「版面分割 + 图例自校准字典 + 旋转符号检测与语法OCR + 张量场断线拓扑缝合」</b>的协同流水线，精准替掉人工描线、查图例和补断口这三个最耗时的环节：</p><div class=\"figure\"><svg viewBox=\"0 0 760 270\" width=\"100%\" role=\"img\" aria-label=\"AI地质图件要素提取与拓扑重建流水线\">\n  <defs>\n    <marker id=\"gme-arr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n  </defs>\n  <rect width=\"760\" height=\"270\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">多模态视觉+知识对齐流水线：用「本图图例自校准」与「张量场断线缝合」替代人工描线录属性</text>\n\n  <!-- 模块 1：版面分割 -->\n  <g transform=\"translate(16,38)\">\n    <rect x=\"0\" y=\"0\" width=\"126\" height=\"214\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"126\" height=\"24\" rx=\"6\" fill=\"#12615a\"/>\n    <text x=\"63\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\" fill=\"#fff\">1. 版面分割与去噪</text>\n    <rect x=\"12\" y=\"34\" width=\"102\" height=\"68\" rx=\"4\" fill=\"#f4ebd6\" stroke=\"#737c83\"/>\n    <rect x=\"16\" y=\"38\" width=\"62\" height=\"40\" fill=\"#e3efec\" stroke=\"#12615a\" stroke-width=\"1.2\"/>\n    <text x=\"47\" y=\"61\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#12615a\" font-weight=\"700\">主图区</text>\n    <rect x=\"82\" y=\"38\" width=\"28\" height=\"40\" fill=\"#f7ecdd\" stroke=\"#c27a2c\" stroke-width=\"1.2\"/>\n    <text x=\"96\" y=\"61\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c27a2c\" font-weight=\"700\">图例</text>\n    <rect x=\"16\" y=\"81\" width=\"94\" height=\"16\" fill=\"#e3ecf6\" stroke=\"#3a6ea5\"/>\n    <text x=\"63\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#3a6ea5\">剖面图与责任表</text>\n    <text x=\"12\" y=\"122\" font-size=\"9.5\" fill=\"#424a50\">• 识别 5 类版面子区</text>\n    <text x=\"12\" y=\"138\" font-size=\"9.5\" fill=\"#424a50\">• 光照背景拟合滤除</text>\n    <text x=\"12\" y=\"152\" font-size=\"9.5\" fill=\"#424a50\">  泛黄褐斑与折痕阴影</text>\n    <text x=\"12\" y=\"172\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">• 读取坐标网交点完</text>\n    <text x=\"12\" y=\"186\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">  成控制点地理配准</text>\n  </g>\n\n  <line x1=\"142\" y1=\"95\" x2=\"164\" y2=\"75\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#gme-arr)\"/>\n  <line x1=\"142\" y1=\"155\" x2=\"164\" y2=\"175\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#gme-arr)\"/>\n\n  <!-- 模块 2A (上)：图例栏 Patch-to-Code 字典构建 -->\n  <g transform=\"translate(168,38)\">\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"96\" rx=\"6\" fill=\"#fff\" stroke=\"#c27a2c\" stroke-width=\"1.3\"/>\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"22\" rx=\"5\" fill=\"#c27a2c\"/>\n    <text x=\"91\" y=\"15\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">2A. 图例色块—代号自校准字典</text>\n    <rect x=\"10\" y=\"30\" width=\"26\" height=\"16\" fill=\"#d9c7a3\" stroke=\"#424a50\"/>\n    <text x=\"42\" y=\"42\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">{色块+花纹} ➔ \"P₁m\"</text>\n    <text x=\"10\" y=\"62\" font-size=\"9\" fill=\"#424a50\">知识图谱对齐：旧码 <tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">J₂sh</tspan> ➔ 现标 <tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#12615a\">J₂s</tspan></text>\n    <text x=\"10\" y=\"78\" font-size=\"9\" fill=\"#737c83\">提取年代(早二叠世) + 岩性描述词条</text>\n  </g>\n\n  <!-- 模块 2B (下)：主图符号旋转检测 + OCR -->\n  <g transform=\"translate(168,144)\">\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"108\" rx=\"6\" fill=\"#fff\" stroke=\"#2f7d5b\" stroke-width=\"1.3\"/>\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"22\" rx=\"5\" fill=\"#2f7d5b\"/>\n    <text x=\"91\" y=\"15\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">2B. 主图旋转框检测与注记 OCR</text>\n    <text x=\"10\" y=\"38\" font-size=\"9.5\" fill=\"#15191c\">• 旋转目标检测：产状 <tspan font-family=\"ui-monospace,Consolas,monospace\">┣ 32°</tspan> 走向角</text>\n    <text x=\"10\" y=\"54\" font-size=\"9.5\" fill=\"#15191c\">  与倾向向量回归 + 钻孔 <tspan font-family=\"ui-monospace,Consolas,monospace\">⊕</tspan> 定位</text>\n    <text x=\"10\" y=\"72\" font-size=\"9.5\" fill=\"#6b5aa6\" font-weight=\"700\">• 语法约束 OCR：主字符+上下标树</text>\n    <text x=\"10\" y=\"88\" font-size=\"9\" fill=\"#737c83\">• 输出文字掩膜框 (Text Mask) 供下一步</text>\n    <text x=\"10\" y=\"100\" font-size=\"9\" fill=\"#737c83\">  剔除字符笔画对断层线的干扰</text>\n  </g>\n\n  <line x1=\"350\" y1=\"86\" x2=\"374\" y2=\"120\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#gme-arr)\"/>\n  <line x1=\"350\" y1=\"196\" x2=\"374\" y2=\"160\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#gme-arr)\"/>\n\n  <!-- 模块 3：骨架提取与张量断线缝合 -->\n  <g transform=\"translate(378,38)\">\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"214\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.4\"/>\n    <rect x=\"0\" y=\"0\" width=\"182\" height=\"24\" rx=\"5\" fill=\"#12615a\"/>\n    <text x=\"91\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">3. 骨架提取与张量场断线缝合</text>\n    <!-- 断线缝合核心视觉机制图 -->\n    <rect x=\"12\" y=\"34\" width=\"158\" height=\"86\" rx=\"4\" fill=\"#182026\"/>\n    <line x1=\"22\" y1=\"104\" x2=\"68\" y2=\"76\" stroke=\"#ff7b72\" stroke-width=\"2.2\"/>\n    <line x1=\"112\" y1=\"52\" x2=\"158\" y2=\"26\" stroke=\"#ff7b72\" stroke-width=\"2.2\"/>\n    <rect x=\"68\" y=\"50\" width=\"44\" height=\"26\" fill=\"none\" stroke=\"#8b949e\" stroke-dasharray=\"2 2\"/>\n    <text x=\"90\" y=\"67\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8b949e\" font-family=\"ui-monospace,Consolas,monospace\">Mask</text>\n    <!-- 缝合桥弧 -->\n    <path d=\"M68,76 Q90,64 112,52\" stroke=\"#7ee787\" stroke-width=\"2.4\" stroke-dasharray=\"4 2\" fill=\"none\"/>\n    <circle cx=\"68\" cy=\"76\" r=\"3\" fill=\"#7ee787\"/><circle cx=\"112\" cy=\"52\" r=\"3\" fill=\"#7ee787\"/>\n    <text x=\"12\" y=\"138\" font-size=\"9.5\" fill=\"#15191c\" font-weight=\"700\">核心机制：走向张量投票桥接</text>\n    <text x=\"12\" y=\"154\" font-size=\"9\" fill=\"#424a50\">1) 抹除文字框内笔画，提取单像素骨架；</text>\n    <text x=\"12\" y=\"170\" font-size=\"9\" fill=\"#424a50\">2) 搜索悬挂端点 (Dangles)，计算端点切</text>\n    <text x=\"12\" y=\"184\" font-size=\"9\" fill=\"#424a50\">   向共线性与跨距 (≤ 25px)；</text>\n    <text x=\"12\" y=\"198\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\">3) 自动生成缝合桥，消除断口。</text>\n  </g>\n\n  <line x1=\"560\" y1=\"145\" x2=\"582\" y2=\"145\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#gme-arr)\"/>\n\n  <!-- 模块 4：拓扑成面与属性挂接 -->\n  <g transform=\"translate(586,38)\">\n    <rect x=\"0\" y=\"0\" width=\"158\" height=\"214\" rx=\"6\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.4\"/>\n    <rect x=\"0\" y=\"0\" width=\"158\" height=\"24\" rx=\"5\" fill=\"#3a6ea5\"/>\n    <text x=\"79\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">4. 拓扑造面与属性挂接</text>\n    <g transform=\"translate(12,34)\">\n      <polygon points=\"0,0 56,0 44,68 0,68\" fill=\"#bfa480\" stroke=\"#15191c\" stroke-width=\"1.2\"/>\n      <polygon points=\"56,0 134,0 134,68 44,68\" fill=\"#d1bc8e\" stroke=\"#15191c\" stroke-width=\"1.2\"/>\n      <text x=\"24\" y=\"38\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">P₁m</text>\n      <text x=\"92\" y=\"38\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₃x</text>\n    </g>\n    <text x=\"12\" y=\"122\" font-size=\"9.5\" fill=\"#15191c\" font-weight=\"700\">输出标准 GIS 矢量包：</text>\n    <text x=\"12\" y=\"138\" font-size=\"9\" fill=\"#424a50\">• 平面图半边结构自动构建</text>\n    <text x=\"12\" y=\"152\" font-size=\"9\" fill=\"#424a50\">  零缝隙闭合地层多边形；</text>\n    <text x=\"12\" y=\"168\" font-size=\"9\" fill=\"#424a50\">• 多边形内点包含关联 OCR</text>\n    <text x=\"12\" y=\"182\" font-size=\"9\" fill=\"#424a50\">  代号与图例岩性描述；</text>\n    <text x=\"12\" y=\"198\" font-size=\"9\" fill=\"#2f7d5b\" font-weight=\"700\">• 人工仅复核低置信度 8% 要素</text>\n  </g>\n</svg></div><div class=\"figcap\"><b>图 3</b><span>历史地质图件智能矢量化流水线：版面分割后，「图例自校准分支」与「主图检测+张量断线缝合分支」协同生成闭合拓扑多边形。</span></div><div class=\"callout\"><span class=\"ci\">核心机制</span><span><b>1) 图例栏自监督校准：</b>每幅地质图右侧的图例栏都印着与主图同一批次晒印的色块花纹和地层代号。AI 先裁剪图例建立本图专属的 <code>{RGB+纹理 ➔ 地层代号 ➔ 现行国标编码}</code> 查找表，从而彻底免疫跨年代晒印褪色；<b>2) 掩膜保护与走向张量断线缝合：</b>利用 OCR 文本检测框生成保护掩膜（抹除文字笔画干扰），提取单像素断层/界线骨架后，沿悬挂端点的<b>走向张量场（Orientation Tensor）</b>计算共线性投票，自动跨过文字和折痕桥接断口，生成 100% 闭合的拓扑多边形。</span></div>"},{"no":3,"en":"","title":"需要准备什么","html":"<p>落地该方案不需要从零手标几万张大图。由于每幅地质图的<b>图例栏天然提供了本图的色彩与纹理原型真值</b>，只需准备 30 幅以上具有代表性的历史扫描图件、一份盆地跨年代地层词典，以及约 3,000 个旋转符号框样本即可完成模型微调：</p><div class=\"checklist\"><div class=\"cl-head\"><span>数据准备清单 · 3 项</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">300 dpi+ 历史扫描地质图件</span><span class=\"cl-s\">TIFF / GeoTIFF 彩色扫描原件（含完整图廓、主图、图例栏与责任表），≥ 30 幅</span></span><span class=\"cl-n\">保留原始 RGB 色阶，禁有损高压缩</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">跨年代图例与地层代号对照词典</span><span class=\"cl-s\">覆盖盆地 1950s–2020s 岩石地层单位名称演进表（如 J₂sh ➔ J₂s 沙溪庙组），约 500 条</span></span><span class=\"cl-n\">JSON/CSV 键值对，含上下标规范编码</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">产状符号与断层拓扑标注样本</span><span class=\"cl-s\">旋转框标注的产状/钻孔符号 ≥ 3,000 个，含断口桥接真值的矢量化切片 ≥ 200 张</span></span><span class=\"cl-n\">需标注走向角 (0–360°) 与倾向极性</span></div>\n</div><div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"符号样本分布与图例主图自监督配对机制\">\n  <rect width=\"760\" height=\"225\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- 左半：图例-主图自监督配对机制 -->\n  <g transform=\"translate(16,16)\">\n    <rect x=\"0\" y=\"0\" width=\"386\" height=\"193\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"22\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">为什么不需要海量标注也能跨年代泛化？——图例–主图自监督配对机制</text>\n    <rect x=\"14\" y=\"34\" width=\"122\" height=\"114\" rx=\"5\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n    <text x=\"75\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#c27a2c\">本图图例栏 (自带真值)</text>\n    <rect x=\"24\" y=\"60\" width=\"28\" height=\"18\" fill=\"#d9c7a3\" stroke=\"#424a50\"/>\n    <text x=\"58\" y=\"73\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">P₁m 茅口组</text>\n    <rect x=\"24\" y=\"86\" width=\"28\" height=\"18\" fill=\"#c7d0be\" stroke=\"#424a50\"/>\n    <text x=\"58\" y=\"99\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">J₂sh 沙溪庙</text>\n    <rect x=\"24\" y=\"112\" width=\"28\" height=\"18\" fill=\"#e4d6b8\" stroke=\"#424a50\"/>\n    <text x=\"58\" y=\"125\" font-size=\"9.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">T₃xj 须家河</text>\n\n    <!-- 特征匹配双向箭头 -->\n    <path d=\"M142,69 H224 M142,95 H224 M142,121 H224\" stroke=\"#12615a\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n    <rect x=\"148\" y=\"56\" width=\"70\" height=\"78\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n    <text x=\"183\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#12615a\">色彩+纹理</text>\n    <text x=\"183\" y=\"92\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#12615a\">原型编码器</text>\n    <text x=\"183\" y=\"110\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#424a50\">同图同批次晒印</text>\n    <text x=\"183\" y=\"123\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#424a50\">色偏完全一致</text>\n\n    <rect x=\"230\" y=\"34\" width=\"142\" height=\"114\" rx=\"5\" fill=\"#fbfaf7\" stroke=\"#12615a\"/>\n    <text x=\"301\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#12615a\">主图区像素与OCR双校验</text>\n    <text x=\"238\" y=\"72\" font-size=\"9\" fill=\"#424a50\">• 色块纹理距离锁定候选层</text>\n    <text x=\"238\" y=\"92\" font-size=\"9\" fill=\"#424a50\">• 约束主图 OCR 词表范围</text>\n    <text x=\"238\" y=\"112\" font-size=\"9\" fill=\"#2f7d5b\" font-weight=\"700\">• 即使下标模糊，「P?m」</text>\n    <text x=\"238\" y=\"126\" font-size=\"9\" fill=\"#2f7d5b\" font-weight=\"700\">  也能被图例唯一纠正为 P₁m</text>\n\n    <text x=\"14\" y=\"170\" font-size=\"9.5\" fill=\"#737c83\">结论：每幅地质图自带的图例栏就是该图最准确的「单样本提示词 (One-Shot Prompt)」。</text>\n  </g>\n\n  <!-- 右半：训练与微调样本规模分布 -->\n  <g transform=\"translate(414,16)\">\n    <rect x=\"0\" y=\"0\" width=\"330\" height=\"193\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"22\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">微调数据集构成与标注工作量（30 幅历史图件即可启动）</text>\n    <g transform=\"translate(14,38)\" font-size=\"10\" fill=\"#424a50\">\n      <text x=\"0\" y=\"14\">地层代号切片 (含上下标)</text>\n      <rect x=\"132\" y=\"3\" width=\"145\" height=\"14\" rx=\"3\" fill=\"#6b5aa6\"/>\n      <text x=\"282\" y=\"14\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#6b5aa6\">4,500 处</text>\n\n      <text x=\"0\" y=\"42\">产状符号旋转框 (┣ + 倾角)</text>\n      <rect x=\"132\" y=\"31\" width=\"118\" height=\"14\" rx=\"3\" fill=\"#2f7d5b\"/>\n      <text x=\"255\" y=\"42\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#2f7d5b\">3,200 处</text>\n\n      <text x=\"0\" y=\"70\">断层逆冲齿/正断层符号</text>\n      <rect x=\"132\" y=\"59\" width=\"82\" height=\"14\" rx=\"3\" fill=\"#b4483c\"/>\n      <text x=\"220\" y=\"70\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#b4483c\">1,800 处</text>\n\n      <text x=\"0\" y=\"98\">探井钻孔与矿点符号 (⊕)</text>\n      <rect x=\"132\" y=\"87\" width=\"64\" height=\"14\" rx=\"3\" fill=\"#3a6ea5\"/>\n      <text x=\"202\" y=\"98\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#3a6ea5\">1,200 处</text>\n\n      <text x=\"0\" y=\"126\">图例色块–代号自动裁剪对</text>\n      <rect x=\"132\" y=\"115\" width=\"96\" height=\"14\" rx=\"3\" fill=\"#c27a2c\"/>\n      <text x=\"234\" y=\"126\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\" fill=\"#c27a2c\">2,400 对(免手标)</text>\n    </g>\n    <text x=\"14\" y=\"180\" font-size=\"9.5\" fill=\"#737c83\">注：可先用合成渲染引擎生成 10,000 张带折痕噪声的假图预训练。</text>\n  </g>\n</svg></div><div class=\"figcap\"><b>图 4</b><span>利用图例栏构建单图自监督色彩/纹理原型（左）与落地所需微调样本规模分布（右）。</span></div>"},{"no":4,"en":"","title":"难度与参考方向","html":"<p>整体落地难度为<b>中等</b>。90 年代以后的胶印地质图可实现 95% 以上全自动矢量化；而 50–70 年代的手绘蓝晒图、重度霉斑折痕图以及密集薄互层区则是主要难点所在。工程上需重点防范<b>「断线缝合跨距过大导致相邻平行界线错误粘连」</b>，通过法向梯度屏障与置信度分级复核，将人工介入严格控制在 8%–10% 的低置信度要素内。</p><div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"扫描退化与压盖程度对拓扑闭合率的影响及技术难度剖析\">\n  <rect width=\"760\" height=\"225\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- 左：不同方法在退化等级下的拓扑闭合率曲线 -->\n  <g transform=\"translate(16,14)\">\n    <rect x=\"0\" y=\"0\" width=\"404\" height=\"196\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">不同退化与文字压盖密度下的多边形拓扑闭合率对比</text>\n    <g transform=\"translate(42,34)\">\n      <line x1=\"0\" y1=\"0\" x2=\"340\" y2=\"0\" stroke=\"#e7e3da\"/><text x=\"-6\" y=\"4\" text-anchor=\"end\" font-size=\"9\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">100%</text>\n      <line x1=\"0\" y1=\"40\" x2=\"340\" y2=\"40\" stroke=\"#e7e3da\"/><text x=\"-6\" y=\"44\" text-anchor=\"end\" font-size=\"9\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">75%</text>\n      <line x1=\"0\" y1=\"80\" x2=\"340\" y2=\"80\" stroke=\"#e7e3da\"/><text x=\"-6\" y=\"84\" text-anchor=\"end\" font-size=\"9\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">50%</text>\n      <line x1=\"0\" y1=\"120\" x2=\"340\" y2=\"120\" stroke=\"#e7e3da\"/><text x=\"-6\" y=\"124\" text-anchor=\"end\" font-size=\"9\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">25%</text>\n      <!-- 曲线 1：带张量缝合+图例自校准 AI 方案 -->\n      <polyline fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.5\" points=\"10,4 115,8 225,18 330,36\"/>\n      <circle cx=\"10\" cy=\"4\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"115\" cy=\"8\" r=\"3.5\" fill=\"#12615a\"/>\n      <circle cx=\"225\" cy=\"18\" r=\"3.5\" fill=\"#12615a\"/><circle cx=\"330\" cy=\"36\" r=\"3.5\" fill=\"#12615a\"/>\n      <!-- 曲线 2：无断线缝合的纯语义分割 -->\n      <polyline fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"2\" stroke-dasharray=\"5 3\" points=\"10,22 115,46 225,78 330,106\"/>\n      <!-- 曲线 3：传统颜色阈值二值化追踪 -->\n      <polyline fill=\"none\" stroke=\"#b4483c\" stroke-width=\"1.8\" stroke-dasharray=\"2 2\" points=\"10,42 115,82 225,112 330,126\"/>\n\n      <text x=\"10\" y=\"138\" text-anchor=\"middle\" font-size=\"9\" fill=\"#424a50\">轻度(90年代胶印)</text>\n      <text x=\"115\" y=\"138\" text-anchor=\"middle\" font-size=\"9\" fill=\"#424a50\">中度(70年代晒印)</text>\n      <text x=\"225\" y=\"138\" text-anchor=\"middle\" font-size=\"9\" fill=\"#424a50\">重度(折痕+黄斑)</text>\n      <text x=\"320\" y=\"138\" text-anchor=\"middle\" font-size=\"9\" fill=\"#b4483c\">极重(手绘蓝晒图)</text>\n    </g>\n    <text x=\"16\" y=\"186\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\">— 本案张量缝合+图例校准</text>\n    <text x=\"158\" y=\"186\" font-size=\"9\" fill=\"#c27a2c\">- - 纯像素分割(无拓扑缝合)</text>\n    <text x=\"302\" y=\"186\" font-size=\"9\" fill=\"#b4483c\">··· 传统阈值追踪</text>\n  </g>\n\n  <!-- 右：四维技术难度剖析 -->\n  <g transform=\"translate(432,14)\">\n    <rect x=\"0\" y=\"0\" width=\"312\" height=\"196\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">关键技术难点与工程应对策略</text>\n    <g transform=\"translate(12,34)\" font-size=\"9.5\" fill=\"#424a50\">\n      <rect x=\"0\" y=\"0\" width=\"288\" height=\"34\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <text x=\"8\" y=\"14\" font-weight=\"700\" fill=\"#b4483c\">难点 1：密集薄互层区平行界线粘连 (高难)</text>\n      <text x=\"8\" y=\"28\" fill=\"#737c83\">对策：引入法向梯度屏障，限制缝合搜索锥角 ≤ ±18°</text>\n\n      <rect x=\"0\" y=\"40\" width=\"288\" height=\"34\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <text x=\"8\" y=\"54\" font-weight=\"700\" fill=\"#c27a2c\">难点 2：上下标复杂地层代号如 P₁m²ᵃ (中高难)</text>\n      <text x=\"8\" y=\"68\" fill=\"#737c83\">对策：二维位置编码 Transformer OCR + 地质年代语法树校验</text>\n\n      <rect x=\"0\" y=\"80\" width=\"288\" height=\"34\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <text x=\"8\" y=\"94\" font-weight=\"700\" fill=\"#3a6ea5\">难点 3：产状符号旋转角 0°–360° 连续回归 (中难)</text>\n      <text x=\"8\" y=\"108\" fill=\"#737c83\">对策：Circular Smooth Label 旋转框检测 + 倾向短线极性判别</text>\n\n      <rect x=\"0\" y=\"120\" width=\"288\" height=\"34\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <text x=\"8\" y=\"134\" font-weight=\"700\" fill=\"#12615a\">难点 4：晒印图纸非线性拉伸配准 (中低难)</text>\n      <text x=\"8\" y=\"148\" fill=\"#737c83\">对策：自动检测图廓经纬网十字丝交点，薄板样条(TPS)纠偏</text>\n    </g>\n  </g>\n</svg></div><div class=\"figcap\"><b>图 5</b><span>不同图纸退化程度下的拓扑闭合率衰减曲线（左）与四大工程技术难点剖析（右）。</span></div><div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/cv\">版面分割与目标检测<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">旋转框产状识别 (OBB)<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/nlp\">地层代号语法树 OCR<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/nlp\">跨年代图例知识对齐<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">张量场断线拓扑缝合<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"历史地质图件智能提取与拓扑矢量化落地流程","lead":["本流程将「单幅图 1.5–2 人·天的人工描线录属性」压缩至「20 分钟算法批处理 + 10 分钟低置信度悬挂点与上下标复核」，直接输出可导入三维地质建模与 GIS 库的标准 GeoJSON 图层。"],"stats":[["单幅处理耗时","25 分钟 (原 1.8 人·天)"],["多边形拓扑闭合率","≥ 98.5%"],["人工复核比例","仅复核低置信度 8%"]],"steps":[{"name":"版面分割与图纸退化去噪","role":"数据","do":"基于版面检测网络分离主图区、图例栏、剖面图与责任表；用多项式背景光照拟合消除纸张泛黄褐斑，检测图廓经纬网交点完成 TPS 地理配准。","effect":"主图与图例裁切准确率 > 99%，晒印底色不均标准差降低 75%，配准残差 ≤ 1.5 像素。","trap":"切勿直接做全局二值化——那会把浅黄色地层色块和细微的正断层短线一并抹掉。"},{"name":"图例色块—地层代号OCR字典构建","role":"算法","do":"在图例栏成对检测色块矩形（Patch）与右侧地层说明文本，提取色块 LAB 色彩直方图与 Gabor 岩性花纹特征，并将旧地层代号（如 J₂sh）通过地质词典对齐至国标代号（J₂s）。","effect":"自动生成当前图幅专属的「色彩纹理 ⇄ 地层代号/年代/岩性」查找表，跨年代代号映射准确率 > 98%。","trap":"部分老图同一图例色块包含上下两个亚段代号，需按版面垂直对齐关系精确绑定。"},{"name":"主图符号检测与地层注记识别","role":"模型","do":"用旋转目标检测器（Oriented R-CNN）定位产状符号（┣）走向角与探井符号（⊕），用带二维位置编码的 OCR 识别上下标地层代号（如 P₂l、T₃x）及倾角数字，同时输出文字边界掩膜（Text Mask）。","effect":"产状与钻孔符号检出 F1 ≥ 94%，走向角误差 ≤ ±2°，地层代号经图例词表约束后识别率达 96.8%。","trap":"产状符号的倾向短线极易与岩石花纹混淆，必须联合旁侧倾角数字（如 32°）做空间配对校验。"},{"name":"断层与界线骨架提取及断线缝合","role":"算法","do":"先用第 3 步的文字掩膜剔除注记笔画干扰，再经 U-Net 提取断层与地层界线概率图并细化为单像素骨架；搜索所有悬挂端点（Dangles），在最大跨距容差（18–26 px）与切向锥角（±18°）内沿走向张量场自动桥接断口。","effect":"由「字压线」和纸张折痕造成的断口缝合率达 98% 以上，界线中心线 Hausdorff 偏移 ≤ 1.8 px。","trap":"缝合最大跨距切忌设得过大（如 > 34 px），否则会在薄互层区把相邻平行界线错误拉扯粘连！"},{"name":"拓扑多边形构建与属性挂接验收","role":"应用","do":"基于闭合弧段构建半边平面拓扑图（Planar Graph Polygonization），通过点在多边形内包含测试与图例色彩距离双重投票挂接地层属性，高亮剩余悬挂点供人工一键复核。","effect":"输出 100% 拓扑闭合、属性完整的 GeoJSON 地层多边形、断层线与产状点图层。","trap":"没有注记文字的狭长断层夹块（断片）不能丢弃，应回退使用图例色彩/花纹原型自动赋属性。"}],"metrics":{"title":"流程分镜与验收指标","html":"<p>以下五步分镜展示同一块含折痕与注记压盖的历史地质图切片，如何从泛黄扫描原件逐步转化为闭合 GIS 矢量多边形与结构化属性表：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"历史地质图件要素提取五步流程分镜\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Panel 01 -->\n  <g transform=\"translate(12,14)\">\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"22\" rx=\"5\" fill=\"#12615a\"/>\n    <text x=\"8\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n    <text x=\"26\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">版面分割与退化去噪</text>\n    <rect x=\"10\" y=\"30\" width=\"118\" height=\"106\" rx=\"4\" fill=\"#f2e4c6\" stroke=\"#737c83\"/>\n    <circle cx=\"52\" cy=\"74\" r=\"32\" fill=\"#c27a2c\" fill-opacity=\"0.22\"/>\n    <path d=\"M10,94 L128,104\" stroke=\"#faf5e8\" stroke-width=\"3\"/>\n    <path d=\"M58,30 L42,136\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n    <rect x=\"14\" y=\"34\" width=\"76\" height=\"68\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/>\n    <rect x=\"94\" y=\"34\" width=\"30\" height=\"68\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/>\n    <text x=\"69\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">分离主图/图例 + 滤除黄斑</text>\n    <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">背景光照拟合消除晒印色偏</text>\n  </g>\n  <!-- Panel 02 -->\n  <g transform=\"translate(161,14)\">\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"22\" rx=\"5\" fill=\"#c27a2c\"/>\n    <text x=\"8\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n    <text x=\"26\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">图例OCR字典构建</text>\n    <rect x=\"10\" y=\"30\" width=\"118\" height=\"106\" rx=\"4\" fill=\"#fbf8f1\" stroke=\"#c27a2c\"/>\n    <rect x=\"16\" y=\"38\" width=\"24\" height=\"15\" fill=\"#d9c7a3\" stroke=\"#424a50\"/>\n    <text x=\"45\" y=\"49\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">T₁j 嘉陵江组</text>\n    <rect x=\"16\" y=\"60\" width=\"24\" height=\"15\" fill=\"#c7d0be\" stroke=\"#424a50\"/>\n    <text x=\"45\" y=\"71\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#12615a\" font-weight=\"700\">J₂sh ➔ J₂s</text>\n    <rect x=\"16\" y=\"82\" width=\"24\" height=\"15\" fill=\"#e4d6b8\" stroke=\"#424a50\"/>\n    <text x=\"45\" y=\"93\" font-size=\"9\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">P₂c 长兴组</text>\n    <text x=\"16\" y=\"120\" font-size=\"8.5\" fill=\"#6b5aa6\" font-family=\"ui-monospace,Consolas,monospace\">{RGB,纹理} ➔ 标准代号</text>\n    <text x=\"69\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">生成本图专属查找字典</text>\n    <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">解决跨年代旧代号与晒印褪色</text>\n  </g>\n  <!-- Panel 03 -->\n  <g transform=\"translate(310,14)\">\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"22\" rx=\"5\" fill=\"#2f7d5b\"/>\n    <text x=\"8\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n    <text x=\"26\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">符号检测与注记OCR</text>\n    <rect x=\"10\" y=\"30\" width=\"118\" height=\"106\" rx=\"4\" fill=\"#f7f2e4\" stroke=\"#737c83\"/>\n    <path d=\"M68,30 L52,136\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n    <!-- 旋转框产状 -->\n    <rect x=\"18\" y=\"44\" width=\"34\" height=\"20\" fill=\"none\" stroke=\"#2f7d5b\" stroke-width=\"1.4\"/>\n    <text x=\"22\" y=\"58\" font-size=\"9\" font-weight=\"700\" fill=\"#2f7d5b\" font-family=\"ui-monospace,Consolas,monospace\">┣ 32°</text>\n    <!-- 压线OCR框 -->\n    <rect x=\"44\" y=\"72\" width=\"34\" height=\"18\" fill=\"rgba(107,90,166,0.18)\" stroke=\"#6b5aa6\" stroke-width=\"1.4\"/>\n    <text x=\"61\" y=\"85\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₁j</text>\n    <rect x=\"84\" y=\"96\" width=\"36\" height=\"18\" fill=\"rgba(58,110,165,0.15)\" stroke=\"#3a6ea5\" stroke-width=\"1.4\"/>\n    <text x=\"102\" y=\"109\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#3a6ea5\" font-family=\"ui-monospace,Consolas,monospace\">⊕ZK1</text>\n    <text x=\"69\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">定位点要素并生成文字掩膜</text>\n    <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">同时输出字符框供断线保护</text>\n  </g>\n  <!-- Panel 04 -->\n  <g transform=\"translate(459,14)\">\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"22\" rx=\"5\" fill=\"#12615a\"/>\n    <text x=\"8\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n    <text x=\"26\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">骨架提取与断线缝合</text>\n    <rect x=\"10\" y=\"30\" width=\"118\" height=\"106\" rx=\"4\" fill=\"#182026\"/>\n    <line x1=\"68\" y1=\"30\" x2=\"62\" y2=\"68\" stroke=\"#ff7b72\" stroke-width=\"2.2\"/>\n    <line x1=\"57\" y1=\"96\" x2=\"50\" y2=\"136\" stroke=\"#ff7b72\" stroke-width=\"2.2\"/>\n    <path d=\"M62,68 L57,96\" stroke=\"#7ee787\" stroke-width=\"2.6\" stroke-dasharray=\"4 2\"/>\n    <circle cx=\"62\" cy=\"68\" r=\"3\" fill=\"#7ee787\"/><circle cx=\"57\" cy=\"96\" r=\"3\" fill=\"#7ee787\"/>\n    <line x1=\"10\" y1=\"106\" x2=\"128\" y2=\"114\" stroke=\"#58a6ff\" stroke-width=\"1.6\"/>\n    <text x=\"69\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">张量场桥接压盖与折痕断口</text>\n    <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">消除全部悬挂端点 (Dangles)</text>\n  </g>\n  <!-- Panel 05 -->\n  <g transform=\"translate(608,14)\">\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n    <rect x=\"0\" y=\"0\" width=\"138\" height=\"22\" rx=\"5\" fill=\"#3a6ea5\"/>\n    <text x=\"8\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n    <text x=\"26\" y=\"15\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">拓扑造面与属性验收</text>\n    <g transform=\"translate(10,30)\">\n      <polygon points=\"0,0 58,0 45,76 0,76\" fill=\"#bfa480\" stroke=\"#15191c\" stroke-width=\"1.2\"/>\n      <polygon points=\"58,0 118,0 118,84 45,76\" fill=\"#b0bfa3\" stroke=\"#15191c\" stroke-width=\"1.2\"/>\n      <polygon points=\"0,76 45,76 118,84 118,106 0,106\" fill=\"#e3dbc3\" stroke=\"#15191c\" stroke-width=\"1.2\"/>\n      <text x=\"26\" y=\"44\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">T₁j</text>\n      <text x=\"84\" y=\"44\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">J₂s</text>\n      <text x=\"58\" y=\"96\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">P₂c</text>\n    </g>\n    <text x=\"69\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#2f7d5b\">100% 闭合 GeoJSON 输出</text>\n    <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">自动挂接年代、岩性与产状属性</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步智能矢量化流程分镜：从含折痕黄斑的原始扫描图（01）到闭合 GIS 多边形与属性挂接（05）。</span></div>\n\n<div class=\"figure\"><svg viewBox=\"0 0 760 185\" width=\"100%\" role=\"img\" aria-label=\"三大核心验收指标示意图\">\n  <rect width=\"760\" height=\"185\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- 指标 1：旋转符号检测 mAP@0.5 与角度误差 -->\n  <g transform=\"translate(14,14)\">\n    <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11\" font-weight=\"700\" fill=\"#2f7d5b\">1. 符号检测 mAP@0.5 与走向角误差</text>\n    <rect x=\"26\" y=\"38\" width=\"66\" height=\"42\" fill=\"rgba(47,125,91,0.12)\" stroke=\"#2f7d5b\" stroke-width=\"1.5\"/>\n    <rect x=\"30\" y=\"42\" width=\"64\" height=\"40\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/>\n    <text x=\"58\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\" font-family=\"ui-monospace,Consolas,monospace\">┣ 32°</text>\n    <text x=\"104\" y=\"48\" font-size=\"9.5\" fill=\"#424a50\">• 旋转框 IoU ≥ 0.5</text>\n    <text x=\"104\" y=\"64\" font-size=\"9.5\" fill=\"#424a50\">• 走向角误差 |Δθ| ≤ 3°</text>\n    <text x=\"104\" y=\"80\" font-size=\"9.5\" fill=\"#2f7d5b\" font-weight=\"700\">• 参考基准线：mAP ≥ 92%</text>\n    <text x=\"12\" y=\"112\" font-size=\"9\" fill=\"#737c83\">同时验证产状符号与旁侧倾角数字的空间配对正确率</text>\n    <text x=\"12\" y=\"136\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：F1 = 95.2%，角误差 ±1.6°</text>\n  </g>\n\n  <!-- 指标 2：地层代号 OCR 字符准确率 (1-CER) -->\n  <g transform=\"translate(263,14)\">\n    <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11\" font-weight=\"700\" fill=\"#6b5aa6\">2. 地层代号完整匹配率与图例对齐率</text>\n    <rect x=\"16\" y=\"34\" width=\"202\" height=\"48\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n    <text x=\"26\" y=\"54\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">主图 OCR: \"J\" + 下标\"2\" + \"s\"</text>\n    <text x=\"26\" y=\"72\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#6b5aa6\">语法树校验 ➔ 对齐图例「J₂s 沙溪庙组」</text>\n    <text x=\"12\" y=\"104\" font-size=\"9.5\" fill=\"#424a50\">• 严格全字符匹配（主字母+上下标全对才算对）</text>\n    <text x=\"12\" y=\"120\" font-size=\"9.5\" fill=\"#424a50\">• 经图例词典约束后，上下标误识率下降 72%</text>\n    <text x=\"12\" y=\"136\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：完整代号准确率 = 96.8%</text>\n  </g>\n\n  <!-- 指标 3：多边形拓扑闭合率与 Hausdorff 距离 -->\n  <g transform=\"translate(512,14)\">\n    <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n    <text x=\"12\" y=\"20\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">3. 多边形拓扑闭合率与边界距离误差</text>\n    <g transform=\"translate(18,34)\">\n      <path d=\"M4,34 Q48,4 96,22 T188,14\" stroke=\"#12615a\" stroke-width=\"2.2\" fill=\"none\"/>\n      <path d=\"M4,42 Q48,12 96,30 T188,22\" stroke=\"#b4483c\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\" fill=\"none\"/>\n      <line x1=\"96\" y1=\"22\" x2=\"96\" y2=\"30\" stroke=\"#15191c\" stroke-width=\"1.5\"/>\n      <text x=\"102\" y=\"45\" font-size=\"9\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Hausdorff d_H ≤ 1.8px</text>\n    </g>\n    <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 悬挂端点 (Dangles) 清零率 ≥ 98%</text>\n    <text x=\"12\" y=\"114\" font-size=\"9.5\" fill=\"#424a50\">• 界线 Hausdorff 偏移 ≤ 2.0 px (合图面 0.2mm)</text>\n    <text x=\"12\" y=\"136\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：闭合率 100% (5/5)，零悬挂点</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>工程交付三大定量验收标准：旋转符号 mAP@0.5、上下标地层代号完整匹配率、以及多边形拓扑闭合率与界线 Hausdorff 距离。</span></div>"},"fails":[{"name":"缝合跨距过大引发平行界线粘连","why":"当断线缝合跨距设得超过相邻薄地层间距（如 ≥ 36 px）时，算法会将两条平行的地层界线横向桥接，导致多边形拓扑畸变。"},{"name":"重度霉斑与十字折痕造成上下标误识","why":"年代久远的晒印图在折痕处纸张纤维破裂，下标数字「₁/₂/₃」残缺，需依赖图例栏色彩纹理距离联合投票纠错。"},{"name":"无注记微小断片属性漏挂接","why":"大断层带内部常夹有面积狭小、未印地层代号的构造透镜体，纯靠 OCR 包含关联会漏赋属性，必须启用图例色块纹理匹配兜底。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":1020}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>历史地质图件要素检测、OCR与拓扑矢量化</title>\n<link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"topbar\">\n    <h1>历史地质图件要素检测、OCR与拓扑矢量化</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"stepPill\"><i></i><span>步骤 05 · 拓扑多边形构建与属性挂接</span></span>\n    <span class=\"pill ok\" id=\"topoPill\"><i></i><span>拓扑闭合 5/5 · 零悬挂点</span></span>\n  </header>\n\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" data-step=\"1\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">版面分割与图纸退化去噪</span>\n    </button>\n    <button type=\"button\" data-step=\"2\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">图例色块—地层代号OCR字典构建</span>\n    </button>\n    <button type=\"button\" data-step=\"3\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">主图符号检测与地层注记识别</span>\n    </button>\n    <button type=\"button\" data-step=\"4\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">断层与界线骨架提取及断线缝合</span>\n    </button>\n    <button type=\"button\" class=\"on\" data-step=\"5\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">拓扑多边形构建与属性挂接验收</span>\n    </button>\n  </nav>\n\n  <div class=\"bench\">\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>图层视图模式</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">点击切换底图</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"seg-col\" id=\"modeSeg\">\n            <button type=\"button\" class=\"on\" data-mode=\"overlay\">\n              <span>扫描原图+检测叠加</span>\n              <span class=\"sub\">SCAN+AI</span>\n            </button>\n            <button type=\"button\" data-mode=\"vector\">\n              <span>仅矢量化拓扑成图</span>\n              <span class=\"sub\">GIS VEC</span>\n            </button>\n            <button type=\"button\" data-mode=\"skeleton\">\n              <span>骨架与断线缝合细节</span>\n              <span class=\"sub\">TOPOLOGY</span>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>退化与提取参数控制</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>图纸泛黄与折痕噪声</span>\n              <output id=\"noiseVal\">0.25</output>\n            </div>\n            <input type=\"range\" id=\"noiseSlider\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.25\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>符号与OCR检测置信度阈值</span>\n              <output id=\"confVal\">0.60</output>\n            </div>\n            <input type=\"range\" id=\"confSlider\" min=\"0.35\" max=\"0.90\" step=\"0.05\" value=\"0.60\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>断线拓扑缝合最大跨距 px</span>\n              <output id=\"gapVal\">22 px</output>\n            </div>\n            <input type=\"range\" id=\"gapSlider\" min=\"0\" max=\"40\" step=\"2\" value=\"22\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkSymbols\" checked>\n            <span>显示符号检测框与产状读数</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkOcr\" checked>\n            <span>显示地层代号 OCR 识别结果</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkLegendJoin\" checked>\n            <span>启用图例自动属性挂接</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkDangles\" checked>\n            <span>高亮未闭合拓扑悬挂点 (Dangles)</span>\n          </label>\n\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn primary\" id=\"btnPlay\">▶ 步进演示</button>\n            <button type=\"button\" class=\"btn\" id=\"btnReset\">↺ 重置参数</button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>经典失灵工况预设</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">一键复现</span>\n        </div>\n        <div class=\"card-b\" style=\"display:flex;flex-direction:column;gap:6px\">\n          <button type=\"button\" class=\"btn block\" data-preset=\"optimal\">✓ 标准最优缝合 (跨距 22px)</button>\n          <button type=\"button\" class=\"btn block\" data-preset=\"unbridged\">⚠ 注记压盖断线未缝合 (跨距 0px)</button>\n          <button type=\"button\" class=\"btn block\" data-preset=\"overmerge\">✗ 跨距过大平行界线粘连 (40px)</button>\n          <button type=\"button\" class=\"btn block\" data-preset=\"heavynoise\">⚠ 重度泛黄折痕退化 (噪声 0.85)</button>\n        </div>\n      </div>\n    </aside>\n\n    <main class=\"stage\">\n      <section class=\"view\">\n        <div class=\"view-h\">\n          <span>1:50,000 历史扫描地质图件工作台（川东华蓥山背斜北段幅 · 1978年晒印扫描件）</span>\n          <span class=\"sp\"></span>\n          <span class=\"legend\">\n            <span><i style=\"background:#2f7d5b\"></i>产状符号 (8)</span>\n            <span><i style=\"background:#3a6ea5\"></i>探井钻孔 (5)</span>\n            <span><i class=\"line\" style=\"background:#b4483c\"></i>断层/逆冲齿 (3)</span>\n            <span><i class=\"dash\" style=\"color:#12615a\"></i>张量断线缝合桥</span>\n          </span>\n        </div>\n\n        <div class=\"map-wrap\" id=\"mapWrap\">\n          <canvas id=\"mapCanvas\" width=\"860\" height=\"460\"></canvas>\n          <div class=\"tip\" id=\"mapTip\"></div>\n        </div>\n\n        <div class=\"insp-bar\" id=\"inspBar\">\n          <div>\n            <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:6px\">\n              <strong style=\"font-size:12px;color:var(--ink)\" id=\"inspTitle\">要素检查器 · 已选中：J₂s 沙溪庙组（主图多边形 ⇄ 图例项联动）</strong>\n              <span class=\"badge ok\" id=\"inspBadge\">已闭合 · 图例已对齐</span>\n            </div>\n            <div class=\"insp-kv\" id=\"inspKv\"></div>\n          </div>\n          <pre class=\"insp-json\" id=\"inspJson\"></pre>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <section class=\"kpis\" style=\"margin-top:16px\">\n    <div class=\"kpi ok\" id=\"kpiSym\">\n      <div class=\"k\">符号检测 F1 (产状+钻孔)</div>\n      <div class=\"v\" id=\"kpiSymVal\">95.2<small>%</small></div>\n      <div class=\"d\" id=\"kpiSymDesc\">检出 13/13 · 旋转角误差 ±1.6°</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiOcr\">\n      <div class=\"k\">地层代号 OCR 准确率</div>\n      <div class=\"v\" id=\"kpiOcrVal\">96.8<small>%</small></div>\n      <div class=\"d\" id=\"kpiOcrDesc\">上标/下标语法校验已开启</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiGap\">\n      <div class=\"k\">断线拓扑缝合率</div>\n      <div class=\"v\" id=\"kpiGapVal\">100.0<small>%</small></div>\n      <div class=\"d\" id=\"kpiGapDesc\">6/6 处注记压盖与折痕断口已桥接</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpiPoly\">\n      <div class=\"k\">多边形拓扑闭合率</div>\n      <div class=\"v\" id=\"kpiPolyVal\">100.0<small>%</small></div>\n      <div class=\"d\" id=\"kpiPolyDesc\">5/5 地层区闭合 · 悬挂点 0 个</div>\n    </div>\n  </section>\n\n  <section class=\"grid2\" style=\"margin-top:16px\">\n    <div class=\"card\">\n      <div class=\"card-h\">\n        <span>四类要素提取精度对比与阈值—F1 响应曲线</span>\n        <span class=\"sp\"></span>\n        <span class=\"hint\">竖虚线为当前阈值</span>\n      </div>\n      <div class=\"card-b\" style=\"padding:10px 12px\">\n        <svg id=\"f1Svg\" viewBox=\"0 0 520 220\" width=\"100%\" role=\"img\" aria-label=\"四类要素提取精度对比与阈值响应曲线\"></svg>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-h\">\n        <span>自动提取的 GIS 结构化属性表（点击行联动高亮）</span>\n        <span class=\"sp\"></span>\n        <span class=\"hint\" id=\"tblSummary\">共 21 条矢量记录</span>\n      </div>\n      <div class=\"card-b\" style=\"padding:0\">\n        <div class=\"tbl-wrap\">\n          <table class=\"t\" id=\"attrTable\">\n            <thead>\n              <tr>\n                <th>要素ID</th>\n                <th>类别</th>\n                <th>代号 / 读数</th>\n                <th>图例挂接属性</th>\n                <th style=\"text-align:right\">置信度</th>\n                <th>拓扑/质控状态</th>\n              </tr>\n            </thead>\n            <tbody id=\"attrTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"insight\" id=\"insightBox\" style=\"margin-top:16px\">\n    <div class=\"tag\" id=\"insightTag\">机理洞察</div>\n    <div id=\"insightText\"></div>\n  </section>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":9425},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* ===================== 本案例专属样式 ===================== */\nbody{padding:14px 18px 18px}\n.topbar{padding-bottom:10px;margin-bottom:10px}\n.stepper{margin-bottom:10px}\n.stepper button{padding:8px 12px}\n.bench{gap:12px}\n.rail{gap:8px}\n.card-h{padding:7px 12px}\n.card-b{padding:9px 12px}\n.ctl{margin-bottom:8px}\n.divider{margin:8px 0}\n.seg-col{display:flex;flex-direction:column;background:var(--paper-2);border-radius:9px;padding:3px;gap:2px}\n.seg-col button{all:unset;cursor:pointer;font-size:12px;padding:4px 9px;border-radius:7px;color:var(--ink-3);transition:all .15s;display:flex;align-items:center;justify-content:space-between}\n.seg-col button:hover{color:var(--ink)}\n.seg-col button.on{background:var(--surface);color:var(--accent);font-weight:650;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.seg-col button .sub{font-size:10.5px;color:var(--ink-4);font-family:var(--mono)}\n.seg-col button.on .sub{color:var(--accent)}\n\n.map-wrap{position:relative;background:#f4efe4;cursor:pointer;user-select:none}\n.map-wrap canvas{display:block;width:100%;height:auto}\n\n.insp-bar{display:grid;grid-template-columns:1.15fr 1fr;gap:10px;padding:8px 12px;background:var(--paper);border-top:1px solid var(--line);align-items:center}\n.insp-kv{display:grid;grid-template-columns:repeat(3,1fr);gap:4px 8px;font-size:11px}\n.insp-kv div{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:4px 7px}\n.insp-kv .k{font-size:10px;color:var(--ink-3);display:block;line-height:1.15}\n.insp-kv .v{font-family:var(--mono);font-weight:600;color:var(--ink);font-size:11px}\n.insp-json{font-family:var(--mono);font-size:10.5px;line-height:1.35;background:#191e22;color:#d6e2e0;padding:6px 10px;border-radius:7px;overflow-x:auto;white-space:pre;margin:0}\n.insp-json .jk{color:#81c7be}\n.insp-json .js{color:#e8b97a}\n.insp-json .jn{color:#9ec2ff}\n\n.badge{display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:99px;font-size:10.5px;font-weight:600;white-space:nowrap}\n.badge.ok{background:var(--green-l);color:var(--green)}\n.badge.warn{background:var(--amber-l);color:var(--amber)}\n.badge.bad{background:var(--red-l);color:var(--red)}\n.badge.acc{background:var(--accent-l);color:var(--accent)}\n\n.tbl-wrap{max-height:195px;overflow-y:auto}\ntable.t th,table.t td{padding:5px 8px}\ntable.t tr.clickable{cursor:pointer;transition:background .12s}\ntable.t tr.clickable:hover{background:var(--paper-2)}\ntable.t tr.sel{background:var(--accent-l)}\ntable.t tr.sel td{color:var(--ink);font-weight:600}\n.swatch{display:inline-block;width:11px;height:11px;border-radius:3px;border:1px solid rgba(0,0,0,.22);vertical-align:-1px;margin-right:5px}\n\n.btn-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px}\n.kpi{padding:9px 14px}\n.kpi .v{font-size:20px}\n.insight{padding:10px 14px;line-height:1.65}\n@media (max-width:860px){\n  .insp-bar{grid-template-columns:1fr}\n  .insp-kv{grid-template-columns:repeat(2,1fr)}\n}\n","enc":"text","size":13474},{"name":"demo/demo.js","data":"/* =========================================================\n   历史地质图件要素检测、OCR与拓扑矢量化 · 前端交互算法引擎\n   ========================================================= */\n(function () {\n  'use strict';\n\n  var W = 860, H = 460;\n  var MAP_X = 16, MAP_Y = 28, MAP_W = 636, MAP_H = 414;\n  var LEG_X = 666, LEG_Y = 28, LEG_W = 178, LEG_H = 414;\n\n  /* 1. 五个地层单元定义（主图多边形 + 图例项 + 跨年代编码对照） */\n  var FORMATIONS = [\n    {\n      id: 'FM-01', code: 'P₂l', legacyCode: 'P₂l (龙潭煤系)', name: '龙潭组',\n      era: '晚二叠世', litho: '深灰页岩夹煤层及泥质灰岩',\n      color: '#c9b497', vecColor: '#bfa480', hatch: 'brick',\n      baseConf: 0.94, labelPos: { x: 112, y: 125 },\n      reqGaps: ['G1', 'G4'],\n      poly: [[16, 28], [248, 28], [218, 178], [176, 305], [16, 315]]\n    },\n    {\n      id: 'FM-02', code: 'T₃x', legacyCode: 'T₃xj (须家河统)', name: '须家河组',\n      era: '晚三叠世', litho: '灰白厚层长石石英砂岩夹炭质页岩',\n      color: '#d8c8a2', vecColor: '#d1bc8e', hatch: 'dots',\n      baseConf: 0.92, labelPos: { x: 288, y: 148 },\n      reqGaps: ['G1', 'G2', 'G5'],\n      poly: [[248, 28], [435, 28], [402, 195], [356, 325], [176, 305], [218, 178]]\n    },\n    {\n      id: 'FM-03', code: 'J₁z', legacyCode: 'J₁zl (自流井层)', name: '自流井组',\n      era: '早侏罗世', litho: '紫红泥岩与介壳灰岩互层',\n      color: '#c2ccb8', vecColor: '#b0bfa3', hatch: 'slash',\n      baseConf: 0.89, labelPos: { x: 472, y: 142 },\n      reqGaps: ['G2', 'G3'],\n      poly: [[435, 28], [568, 28], [540, 212], [492, 345], [356, 325], [402, 195]]\n    },\n    {\n      id: 'FM-04', code: 'J₂s', legacyCode: 'J₂sh (沙溪庙系)', name: '沙溪庙组',\n      era: '中侏罗世', litho: '紫红色砂质泥岩夹厚层长石砂岩',\n      color: '#e2cfb0', vecColor: '#d9be95', hatch: 'cross',\n      baseConf: 0.96, labelPos: { x: 598, y: 175 },\n      reqGaps: ['G3', 'G6'],\n      poly: [[568, 28], [652, 28], [652, 372], [492, 345], [540, 212]]\n    },\n    {\n      id: 'FM-05', code: 'Q₄', legacyCode: 'Q₄ᵃˡ (近代冲积)', name: '第四系全新统',\n      era: '第四纪全新世', litho: '河谷冲积砂砾石、亚粘土层',\n      color: '#eae4d3', vecColor: '#e3dbc3', hatch: 'wave',\n      baseConf: 0.91, labelPos: { x: 315, y: 392 },\n      reqGaps: ['G4', 'G5', 'G6'],\n      poly: [[16, 315], [176, 305], [356, 325], [492, 345], [652, 372], [652, 442], [16, 442]]\n    }\n  ];\n\n  /* 2. 三条主要断层与界线（含逆冲断层齿、正断层短线、以及被文字/折痕切断的 6 处断口 G1..G6） */\n  var FAULTS = [\n    {\n      id: 'FLT-F1', code: 'F₁ 华蓥山逆冲断层', type: '逆冲断层',\n      sense: '倾向NW · 倾角 42° · 逆冲推覆',\n      pts: [[248, 28], [218, 178], [176, 305], [142, 442]],\n      color: '#b4483c', teeth: 'reverse', baseConf: 0.93,\n      gaps: [\n        { id: 'G1', x: 229, y: 122, span: 18, reason: '注记「P₂l」压盖断层线', dir: -79 },\n        { id: 'G4', x: 182, y: 282, span: 16, reason: '纸张折痕切断逆冲断层', dir: -76 }\n      ]\n    },\n    {\n      id: 'FLT-F2', code: 'F₂ 邻水压扭性断层', type: '逆断层',\n      sense: '倾向SE · 倾角 55° · 压扭平移',\n      pts: [[435, 28], [402, 195], [356, 325], [322, 442]],\n      color: '#b4483c', teeth: 'reverse', baseConf: 0.90,\n      gaps: [\n        { id: 'G2', x: 412, y: 145, span: 20, reason: '注记「T₃x」压盖断层线', dir: -78 },\n        { id: 'G5', x: 368, y: 290, span: 17, reason: '钻孔注记压盖断层界线', dir: -71 }\n      ]\n    },\n    {\n      id: 'FLT-F3', code: 'F₃ 铜锣峡正断层', type: '正断层',\n      sense: '倾向NW · 倾角 64° · 张性正断',\n      pts: [[568, 28], [540, 212], [492, 345], [462, 442]],\n      color: '#b4483c', teeth: 'normal', baseConf: 0.86,\n      gaps: [\n        { id: 'G3', x: 548, y: 158, span: 19, reason: '产状注记「45°」压盖断层', dir: -81 },\n        { id: 'G6', x: 502, y: 318, span: 21, reason: '折痕与不整合界线交汇断口', dir: -70 }\n      ]\n    }\n  ];\n\n  /* 3. 八个地层产状符号（走向 + 倾向短线 + 倾角 OCR） */\n  var DIPS = [\n    { id: 'DIP-01', x: 96,  y: 88,  strike: 22, dip: 32, fm: 'P₂l', baseConf: 0.95 },\n    { id: 'DIP-02', x: 145, y: 228, strike: 18, dip: 38, fm: 'P₂l', baseConf: 0.88 },\n    { id: 'DIP-03', x: 318, y: 86,  strike: 25, dip: 28, fm: 'T₃x', baseConf: 0.96 },\n    { id: 'DIP-04', x: 278, y: 238, strike: 20, dip: 35, fm: 'T₃x', baseConf: 0.91 },\n    { id: 'DIP-05', x: 486, y: 84,  strike: 24, dip: 45, fm: 'J₁z', baseConf: 0.84 },\n    { id: 'DIP-06', x: 448, y: 254, strike: 19, dip: 41, fm: 'J₁z', baseConf: 0.79 },\n    { id: 'DIP-07', x: 604, y: 105, strike: 21, dip: 26, fm: 'J₂s', baseConf: 0.93 },\n    { id: 'DIP-08', x: 576, y: 286, strike: 16, dip: 30, fm: 'J₂s', baseConf: 0.72 }\n  ];\n\n  /* 4. 五口勘探钻孔符号 */\n  var WELLS = [\n    { id: 'WL-01', code: '川科1', x: 122, y: 175, fm: 'P₂l', depth: '2480m', res: '获工业气流', baseConf: 0.97 },\n    { id: 'WL-02', code: '龙深2', x: 328, y: 198, fm: 'T₃x', depth: '3120m', res: '须家河组气层', baseConf: 0.94 },\n    { id: 'WL-03', code: '华参1', x: 348, y: 292, fm: 'T₃x', depth: '2890m', res: '断层遮挡油气显示', baseConf: 0.87 },\n    { id: 'WL-04', code: '邻探3', x: 468, y: 198, fm: 'J₁z', depth: '1950m', res: '自流井组油斑', baseConf: 0.91 },\n    { id: 'WL-05', code: '沙浅4', x: 595, y: 238, fm: 'J₂s', depth: '1420m', res: '低产气显示', baseConf: 0.76 }\n  ];\n\n  /* 状态对象 */\n  var state = {\n    step: 5,\n    mode: 'overlay',\n    noise: 0.25,\n    conf: 0.60,\n    gapPx: 22,\n    showSymbols: true,\n    showOcr: true,\n    legendJoin: true,\n    showDangles: true,\n    selectedId: 'FM-04',\n    playTimer: null\n  };\n\n  /* 计算当前参数下的算法输出与各要素状态 */\n  function computePipeline() {\n    var noisePenalty = state.noise * 0.24;\n    var gapPx = state.gapPx;\n    var overMerge = gapPx >= 34;\n\n    /* 1) 评估 6 个断口的桥接状态 */\n    var gapMap = {};\n    var bridgedCount = 0;\n    var totalGaps = 0;\n    FAULTS.forEach(function (f) {\n      f.gaps.forEach(function (g) {\n        totalGaps++;\n        var effSpan = g.span + Math.round(state.noise * 4);\n        var bridged = gapPx >= effSpan;\n        gapMap[g.id] = {\n          bridged: bridged,\n          effSpan: effSpan,\n          overMerge: overMerge && (g.id === 'G2' || g.id === 'G3')\n        };\n        if (bridged) bridgedCount++;\n      });\n    });\n\n    /* 2) 地层多边形闭合与 OCR 识别 */\n    var closedFormations = 0;\n    var ocrCorrect = 0;\n    var fmResults = FORMATIONS.map(function (fm) {\n      var conf = Math.max(0.38, Math.min(0.99, +(fm.baseConf - noisePenalty * 0.85).toFixed(2)));\n      var detected = conf >= state.conf;\n      var allGapsClosed = fm.reqGaps.every(function (gid) { return gapMap[gid] && gapMap[gid].bridged; });\n      var hasOverMerge = fm.reqGaps.some(function (gid) { return gapMap[gid] && gapMap[gid].overMerge; });\n      var closed = allGapsClosed && !hasOverMerge;\n      if (closed) closedFormations++;\n      if (detected) ocrCorrect++;\n      return {\n        ref: fm, id: fm.id, category: '地层多边形',\n        code: fm.code, name: state.legendJoin ? (fm.name + ' (' + fm.era + ')') : '未挂接图例词典',\n        conf: conf, detected: detected, closed: closed, overMerge: hasOverMerge\n      };\n    });\n\n    /* 3) 断层提取状态 */\n    var fltResults = FAULTS.map(function (f) {\n      var conf = Math.max(0.40, Math.min(0.99, +(f.baseConf - noisePenalty * 0.9).toFixed(2)));\n      var detected = conf >= state.conf;\n      var bCnt = f.gaps.filter(function (g) { return gapMap[g.id].bridged; }).length;\n      var over = f.gaps.some(function (g) { return gapMap[g.id].overMerge; });\n      return {\n        ref: f, id: f.id, category: '断层线',\n        code: f.code, name: f.sense,\n        conf: conf, detected: detected,\n        closed: bCnt === f.gaps.length && !over,\n        bridgedCnt: bCnt, totalGaps: f.gaps.length, overMerge: over\n      };\n    });\n\n    /* 4) 产状符号与钻孔检测 */\n    var dipResults = DIPS.map(function (d) {\n      var conf = Math.max(0.36, Math.min(0.99, +(d.baseConf - noisePenalty * 1.05).toFixed(2)));\n      var detected = conf >= state.conf;\n      if (detected && conf > 0.55) ocrCorrect++;\n      return {\n        ref: d, id: d.id, category: '产状符号',\n        code: '┣ ' + d.dip + '° (走向' + d.strike + '°)',\n        name: '所属地层 ' + d.fm,\n        conf: conf, detected: detected, closed: detected\n      };\n    });\n\n    var wellResults = WELLS.map(function (w) {\n      var conf = Math.max(0.38, Math.min(0.99, +(w.baseConf - noisePenalty * 0.95).toFixed(2)));\n      var detected = conf >= state.conf;\n      if (detected) ocrCorrect++;\n      return {\n        ref: w, id: w.id, category: '探井钻孔',\n        code: '⊕ ' + w.code,\n        name: w.res + ' (' + w.depth + ')',\n        conf: conf, detected: detected, closed: detected\n      };\n    });\n\n    /* 假阳性噪声惩罚（当阈值过低且泛黄噪声高时产生伪检） */\n    var falsePos = Math.max(0, Math.round((0.58 - state.conf) * 14 * (0.4 + state.noise)));\n    var symTotal = DIPS.length + WELLS.length;\n    var symTP = dipResults.filter(function (x) { return x.detected; }).length +\n                wellResults.filter(function (x) { return x.detected; }).length;\n    var symFN = symTotal - symTP;\n    var symF1 = (2 * symTP) / Math.max(1, 2 * symTP + falsePos + symFN) * 100;\n\n    var ocrTotal = FORMATIONS.length + DIPS.length + WELLS.length;\n    var ocrAcc = Math.max(42, Math.min(99.2, (ocrCorrect / ocrTotal) * 100 - state.noise * 6.5 - (state.conf > 0.78 ? (state.conf - 0.78) * 35 : 0)));\n\n    var gapRate = (bridgedCount / totalGaps) * 100;\n    if (overMerge) gapRate = Math.max(55, gapRate - (gapPx - 32) * 3.2);\n\n    var dangles = (totalGaps - bridgedCount) * 2 + (overMerge ? 3 : 0);\n    var polyRate = (closedFormations / FORMATIONS.length) * 100;\n    if (!state.legendJoin) polyRate = Math.min(polyRate, 78);\n\n    return {\n      gapMap: gapMap,\n      fmResults: fmResults,\n      fltResults: fltResults,\n      dipResults: dipResults,\n      wellResults: wellResults,\n      symTP: symTP, symTotal: symTotal, falsePos: falsePos,\n      symF1: symF1,\n      ocrAcc: ocrAcc,\n      bridgedCount: bridgedCount, totalGaps: totalGaps,\n      gapRate: gapRate,\n      closedFormations: closedFormations,\n      dangles: dangles,\n      polyRate: polyRate,\n      overMerge: overMerge\n    };\n  }\n\n  /* ---------------------------------------------------------\n     2. Canvas 渲染引擎（主图区 + 右侧图例栏 + 纸张退化 + 拓扑层）\n     --------------------------------------------------------- */\n  var canvas = document.getElementById('mapCanvas');\n  var ctx = canvas.getContext('2d');\n\n  function setupHiDPI() {\n    var dpr = Math.min(window.devicePixelRatio || 1, 2);\n    canvas.width = W * dpr;\n    canvas.height = H * dpr;\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }\n  setupHiDPI();\n\n  function drawPolyPath(c, pts) {\n    c.beginPath();\n    for (var i = 0; i < pts.length; i++) {\n      if (i === 0) c.moveTo(pts[i][0], pts[i][1]);\n      else c.lineTo(pts[i][0], pts[i][1]);\n    }\n    c.closePath();\n  }\n\n  /* 绘制地层花纹（砖墙灰岩、砂岩点阵、泥岩斜线、交错砂泥、冲积波纹） */\n  function drawHatch(c, fm, alpha) {\n    c.save();\n    drawPolyPath(c, fm.poly);\n    c.clip();\n    c.strokeStyle = 'rgba(45,38,28,' + alpha + ')';\n    c.fillStyle = 'rgba(45,38,28,' + alpha + ')';\n    c.lineWidth = 0.8;\n\n    var minX = 16, maxX = 652, minY = 28, maxY = 442;\n    var x, y;\n    if (fm.hatch === 'brick') {\n      for (y = minY; y < maxY; y += 16) {\n        c.beginPath(); c.moveTo(minX, y); c.lineTo(maxX, y); c.stroke();\n        var off = ((y / 16) % 2) * 14;\n        for (x = minX + off; x < maxX; x += 28) {\n          c.beginPath(); c.moveTo(x, y); c.lineTo(x, y + 16); c.stroke();\n        }\n      }\n    } else if (fm.hatch === 'dots') {\n      for (y = minY + 6; y < maxY; y += 14) {\n        for (x = minX + ((y % 28 === 6) ? 6 : 13); x < maxX; x += 16) {\n          c.beginPath(); c.arc(x, y, 1.1, 0, Math.PI * 2); c.fill();\n        }\n      }\n    } else if (fm.hatch === 'slash') {\n      for (x = minX - 300; x < maxX; x += 18) {\n        c.beginPath(); c.moveTo(x, minY); c.lineTo(x + 220, maxY); c.stroke();\n      }\n    } else if (fm.hatch === 'cross') {\n      for (y = minY + 8; y < maxY; y += 18) {\n        for (x = minX + 8; x < maxX; x += 22) {\n          c.beginPath(); c.moveTo(x - 4, y); c.lineTo(x + 4, y);\n          c.moveTo(x, y - 3); c.lineTo(x, y + 3); c.stroke();\n        }\n      }\n    } else if (fm.hatch === 'wave') {\n      for (y = 322; y < maxY; y += 16) {\n        for (x = minX + 10; x < maxX - 10; x += 28) {\n          c.beginPath();\n          c.moveTo(x, y);\n          c.quadraticCurveTo(x + 6, y - 3, x + 12, y);\n          c.stroke();\n        }\n      }\n    }\n    c.restore();\n  }\n\n  function renderMap(res) {\n    ctx.clearRect(0, 0, W, H);\n    var isSkel = state.mode === 'skeleton' || state.step === 4;\n    var isVec = state.mode === 'vector' || state.step === 5 && state.mode === 'vector';\n\n    /* 0. 纸张底色与边框 */\n    ctx.fillStyle = isSkel ? '#182026' : (isVec ? '#faf8f3' : '#f3ebd9');\n    ctx.fillRect(0, 0, W, H);\n\n    /* 顶部图头注记 */\n    ctx.fillStyle = isSkel ? '#9ab0ba' : '#2c261e';\n    ctx.font = 'bold 11.5px \"PingFang SC\",\"Microsoft YaHei\",sans-serif';\n    ctx.fillText('四川省华蓥山背斜北段地质图 (1:50,000) · 图幅号 H-48-70-B', MAP_X, 19);\n    ctx.font = '10.5px \"JetBrains Mono\",Consolas,monospace';\n    ctx.fillStyle = isSkel ? '#7994a0' : '#6c6252';\n    ctx.fillText('106°40\\'E–52\\'E · 图例自校准', LEG_X, 19);\n\n    /* 1. 主图区地层渲染 */\n    FORMATIONS.forEach(function (fm, idx) {\n      var fmRes = res.fmResults[idx];\n      var isSel = state.selectedId === fm.id;\n      ctx.save();\n      drawPolyPath(ctx, fm.poly);\n\n      if (isSkel) {\n        ctx.fillStyle = isSel ? 'rgba(18,97,90,0.32)' : 'rgba(255,255,255,0.03)';\n        ctx.fill();\n      } else if (isVec) {\n        ctx.fillStyle = fmRes.closed ? (state.legendJoin ? fm.vecColor : '#dcd7cc') : 'rgba(180,72,60,0.16)';\n        ctx.fill();\n        drawHatch(ctx, fm, 0.16);\n      } else {\n        ctx.fillStyle = fm.color;\n        ctx.fill();\n        drawHatch(ctx, fm, 0.20);\n      }\n\n      /* 选中高亮或未闭合警示描边 */\n      if (isSel) {\n        ctx.strokeStyle = '#12615a';\n        ctx.lineWidth = 3;\n        ctx.stroke();\n      } else if ((state.step >= 4 || isVec) && !fmRes.closed) {\n        ctx.strokeStyle = 'rgba(180,72,60,0.65)';\n        ctx.setLineDash([5, 4]);\n        ctx.lineWidth = 2;\n        ctx.stroke();\n        ctx.setLineDash([]);\n      }\n      ctx.restore();\n    });\n\n    /* 2. 扫描图纸泛黄污渍与纸张折痕（随 noise 滑杆动态增强，且在第1步展示去噪对比） */\n    if (!isVec && state.noise > 0) {\n      ctx.save();\n      ctx.beginPath(); ctx.rect(MAP_X, MAP_Y, MAP_W, MAP_H); ctx.clip();\n      var nAlpha = state.step === 1 ? state.noise * 0.48 : state.noise * 0.34;\n      var grd = ctx.createRadialGradient(240, 190, 30, 320, 230, 360);\n      grd.addColorStop(0, 'rgba(176,128,52,' + (nAlpha * 0.85) + ')');\n      grd.addColorStop(0.6, 'rgba(160,115,45,' + (nAlpha * 0.45) + ')');\n      grd.addColorStop(1, 'rgba(140,95,35,0)');\n      ctx.fillStyle = grd;\n      ctx.fillRect(MAP_X, MAP_Y, MAP_W, MAP_H);\n\n      /* 贯穿主图的模拟历史纸张折痕（切断 F1、F2、F3 下段） */\n      ctx.strokeStyle = isSkel ? 'rgba(220,170,95,' + (state.noise * 0.65) + ')' : 'rgba(248,242,226,' + (0.45 + state.noise * 0.45) + ')';\n      ctx.lineWidth = 2.5 + state.noise * 2.5;\n      ctx.beginPath();\n      ctx.moveTo(MAP_X, 272);\n      ctx.lineTo(355, 292);\n      ctx.lineTo(MAP_X + MAP_W, 328);\n      ctx.stroke();\n\n      ctx.strokeStyle = 'rgba(125,88,36,' + (state.noise * 0.45) + ')';\n      ctx.lineWidth = 1;\n      ctx.beginPath();\n      ctx.moveTo(MAP_X, 274);\n      ctx.lineTo(355, 294);\n      ctx.lineTo(MAP_X + MAP_W, 330);\n      ctx.stroke();\n      ctx.restore();\n    }\n\n    /* 3. 地层不整合接触界线 (Q4 上边界) */\n    ctx.save();\n    ctx.strokeStyle = isSkel ? '#58a6ff' : '#3a3228';\n    ctx.lineWidth = isSkel ? 1.8 : 1.4;\n    ctx.beginPath();\n    ctx.moveTo(16, 315); ctx.lineTo(176, 305); ctx.lineTo(356, 325);\n    ctx.lineTo(492, 345); ctx.lineTo(652, 372);\n    ctx.stroke();\n    ctx.restore();\n\n    /* 4. 断层线、逆冲断层三角齿、断口 (G1..G6) 与张量缝合桥 */\n    FAULTS.forEach(function (flt) {\n      var isSel = state.selectedId === flt.id;\n      ctx.save();\n      ctx.strokeStyle = isSel ? '#12615a' : (isSkel ? '#ff7b72' : flt.color);\n      ctx.lineWidth = isSel ? 3.4 : (isSkel ? 2.4 : 2.2);\n      ctx.beginPath();\n      for (var i = 0; i < flt.pts.length; i++) {\n        if (i === 0) ctx.moveTo(flt.pts[i][0], flt.pts[i][1]);\n        else ctx.lineTo(flt.pts[i][0], flt.pts[i][1]);\n      }\n      ctx.stroke();\n\n      /* 绘制断层运动学符号（逆冲三角齿 / 正断层短Tick） */\n      for (var k = 0; k < flt.pts.length - 1; k++) {\n        var p0 = flt.pts[k], p1 = flt.pts[k + 1];\n        var mx = (p0[0] + p1[0]) * 0.5, my = (p0[1] + p1[1]) * 0.5;\n        var ang = Math.atan2(p1[1] - p0[1], p1[0] - p0[0]);\n        ctx.save();\n        ctx.translate(mx, my);\n        ctx.rotate(ang);\n        ctx.fillStyle = isSkel ? '#ff7b72' : flt.color;\n        if (flt.teeth === 'reverse') {\n          ctx.beginPath();\n          ctx.moveTo(-6, 0); ctx.lineTo(6, 0); ctx.lineTo(0, -8);\n          ctx.closePath(); ctx.fill();\n        } else {\n          ctx.beginPath();\n          ctx.moveTo(0, 0); ctx.lineTo(0, 8);\n          ctx.stroke();\n        }\n        ctx.restore();\n      }\n\n      /* 模拟文字压盖与折痕造成的断口，以及 AI 断线拓扑缝合桥 */\n      flt.gaps.forEach(function (g) {\n        var gm = res.gapMap[g.id];\n        /* 先擦出原始断口间隙 */\n        ctx.save();\n        ctx.fillStyle = isSkel ? '#182026' : '#f1e7d0';\n        ctx.beginPath();\n        ctx.arc(g.x, g.y, 9, 0, Math.PI * 2);\n        ctx.fill();\n\n        if (gm.bridged && state.step >= 4) {\n          /* 已桥接：绘制青绿色张量场缝合弧线与端点 */\n          ctx.strokeStyle = gm.overMerge ? '#c27a2c' : '#12615a';\n          ctx.lineWidth = 2.6;\n          ctx.setLineDash([4, 2]);\n          ctx.beginPath();\n          ctx.moveTo(g.x + 2, g.y - 10);\n          ctx.lineTo(g.x - 2, g.y + 10);\n          ctx.stroke();\n          ctx.setLineDash([]);\n\n          ctx.fillStyle = gm.overMerge ? '#c27a2c' : '#2f7d5b';\n          ctx.beginPath();\n          ctx.arc(g.x, g.y, 3.5, 0, Math.PI * 2);\n          ctx.fill();\n\n          /* 若跨距过大导致邻近平行线错误粘连，画出误粘连红虚线 */\n          if (gm.overMerge) {\n            ctx.strokeStyle = '#b4483c';\n            ctx.lineWidth = 2;\n            ctx.setLineDash([3, 3]);\n            ctx.beginPath();\n            ctx.moveTo(g.x, g.y);\n            ctx.lineTo(g.x - 58, g.y + 14);\n            ctx.stroke();\n            ctx.setLineDash([]);\n          }\n        } else if (state.showDangles) {\n          /* 未闭合悬挂端点 (Dangle) 红色告警圈 */\n          ctx.strokeStyle = '#b4483c';\n          ctx.lineWidth = 1.8;\n          ctx.beginPath();\n          ctx.arc(g.x, g.y, 10, 0, Math.PI * 2);\n          ctx.stroke();\n          ctx.fillStyle = '#b4483c';\n          ctx.beginPath();\n          ctx.arc(g.x + 2, g.y - 8, 3, 0, Math.PI * 2);\n          ctx.arc(g.x - 2, g.y + 8, 3, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        ctx.restore();\n      });\n      ctx.restore();\n    });\n\n    /* 5. 产状符号（┣ 走向长线 + 倾向短线 + 倾角数字）与检测框 */\n    DIPS.forEach(function (d, idx) {\n      var dRes = res.dipResults[idx];\n      var isSel = state.selectedId === d.id;\n      ctx.save();\n      ctx.translate(d.x, d.y);\n      var rad = (d.strike - 90) * Math.PI / 180;\n      ctx.rotate(rad);\n      ctx.strokeStyle = isSkel ? '#7ee787' : '#1e2428';\n      ctx.lineWidth = 1.8;\n      ctx.beginPath();\n      ctx.moveTo(-10, 0); ctx.lineTo(10, 0);\n      ctx.moveTo(0, 0); ctx.lineTo(0, 7);\n      ctx.stroke();\n      ctx.restore();\n\n      ctx.fillStyle = isSkel ? '#d2dce2' : '#1e2428';\n      ctx.font = 'bold 10.5px \"JetBrains Mono\",Consolas,monospace';\n      ctx.fillText(d.dip + '°', d.x + 8, d.y + 4);\n\n      if ((state.showSymbols || state.step === 3) && state.step >= 3) {\n        ctx.save();\n        ctx.strokeStyle = isSel ? '#12615a' : (dRes.detected ? '#2f7d5b' : '#b4483c');\n        ctx.lineWidth = isSel ? 2.4 : 1.3;\n        if (!dRes.detected) ctx.setLineDash([3, 2]);\n        ctx.strokeRect(d.x - 14, d.y - 12, 44, 24);\n        ctx.restore();\n      }\n    });\n\n    /* 6. 探井钻孔符号（⊕）与检测框 */\n    WELLS.forEach(function (w, idx) {\n      var wRes = res.wellResults[idx];\n      var isSel = state.selectedId === w.id;\n      ctx.save();\n      ctx.strokeStyle = isSkel ? '#79c0ff' : '#b4483c';\n      ctx.lineWidth = 1.6;\n      ctx.beginPath();\n      ctx.arc(w.x, w.y, 6, 0, Math.PI * 2);\n      ctx.moveTo(w.x - 8, w.y); ctx.lineTo(w.x + 8, w.y);\n      ctx.moveTo(w.x, w.y - 8); ctx.lineTo(w.x, w.y + 8);\n      ctx.stroke();\n\n      ctx.fillStyle = isSkel ? '#79c0ff' : '#7a251d';\n      ctx.font = 'bold 10.5px \"PingFang SC\",sans-serif';\n      ctx.fillText(w.code, w.x + 9, w.y + 4);\n\n      if ((state.showSymbols || state.step === 3) && state.step >= 3) {\n        ctx.strokeStyle = isSel ? '#12615a' : (wRes.detected ? '#3a6ea5' : '#b4483c');\n        ctx.lineWidth = isSel ? 2.4 : 1.3;\n        ctx.strokeRect(w.x - 10, w.y - 11, 52, 22);\n      }\n      ctx.restore();\n    });\n\n    /* 7. 地层代号注记与 OCR 识别框 */\n    FORMATIONS.forEach(function (fm, idx) {\n      var fmRes = res.fmResults[idx];\n      var p = fm.labelPos;\n      ctx.save();\n      ctx.font = 'bold 13px \"JetBrains Mono\",Consolas,monospace';\n      ctx.fillStyle = isSkel ? '#f0f6fc' : '#15191c';\n      ctx.fillText(fm.code, p.x, p.y);\n\n      if ((state.showOcr || state.step === 3) && state.step >= 2) {\n        ctx.strokeStyle = fmRes.detected ? '#6b5aa6' : '#b4483c';\n        ctx.fillStyle = fmRes.detected ? 'rgba(107,90,166,0.12)' : 'rgba(180,72,60,0.15)';\n        ctx.lineWidth = 1.3;\n        ctx.fillRect(p.x - 5, p.y - 14, 38, 19);\n        ctx.strokeRect(p.x - 5, p.y - 14, 38, 19);\n      }\n      ctx.restore();\n    });\n\n    /* 步骤 1 专属：版面分割区域边框高亮 */\n    if (state.step === 1) {\n      ctx.save();\n      ctx.strokeStyle = '#12615a';\n      ctx.lineWidth = 2.2;\n      ctx.setLineDash([6, 4]);\n      ctx.strokeRect(MAP_X + 2, MAP_Y + 2, MAP_W - 4, MAP_H - 4);\n      ctx.fillStyle = 'rgba(18,97,90,0.88)';\n      ctx.fillRect(MAP_X + 8, MAP_Y + 8, 185, 22);\n      ctx.fillStyle = '#fff';\n      ctx.font = 'bold 11px \"PingFang SC\",sans-serif';\n      ctx.fillText('区域 ① 主图区 (636×414 px)', MAP_X + 14, MAP_Y + 23);\n      ctx.restore();\n    }\n\n    /* 主图外框 */\n    ctx.strokeStyle = isSkel ? '#30363d' : '#2c261e';\n    ctx.lineWidth = 1.8;\n    ctx.strokeRect(MAP_X, MAP_Y, MAP_W, MAP_H);\n\n    /* 8. 右侧图例栏 (Legend Sidebar) 渲染与联动高亮 */\n    ctx.fillStyle = isSkel ? '#21262d' : '#faf7f0';\n    ctx.fillRect(LEG_X, LEG_Y, LEG_W, LEG_H);\n    ctx.strokeStyle = (state.step === 2) ? '#12615a' : (isSkel ? '#30363d' : '#2c261e');\n    ctx.lineWidth = (state.step === 2) ? 2.4 : 1.5;\n    ctx.strokeRect(LEG_X, LEG_Y, LEG_W, LEG_H);\n\n    ctx.fillStyle = isSkel ? '#e6edf3' : '#15191c';\n    ctx.font = 'bold 12px \"PingFang SC\",sans-serif';\n    ctx.fillText('图 例 栏 (知识字典源)', LEG_X + 12, LEG_Y + 22);\n    ctx.font = '10.5px \"PingFang SC\",sans-serif';\n    ctx.fillStyle = isSkel ? '#8b949e' : '#737c83';\n    ctx.fillText('色块花纹 ⇄ 跨年代代号对齐', LEG_X + 12, LEG_Y + 38);\n\n    FORMATIONS.forEach(function (fm, idx) {\n      var ly = LEG_Y + 52 + idx * 54;\n      var isSel = state.selectedId === fm.id;\n      ctx.save();\n      if (isSel) {\n        ctx.fillStyle = isSkel ? 'rgba(18,97,90,0.35)' : '#e3efec';\n        ctx.fillRect(LEG_X + 5, ly - 4, LEG_W - 10, 48);\n        ctx.strokeStyle = '#12615a';\n        ctx.lineWidth = 1.5;\n        ctx.strokeRect(LEG_X + 5, ly - 4, LEG_W - 10, 48);\n      }\n\n      /* 图例色块 Patch */\n      ctx.fillStyle = fm.color;\n      ctx.fillRect(LEG_X + 10, ly + 2, 34, 24);\n      ctx.strokeStyle = '#3a3228';\n      ctx.lineWidth = 1;\n      ctx.strokeRect(LEG_X + 10, ly + 2, 34, 24);\n\n      /* 图例代号与跨年代映射 */\n      ctx.fillStyle = isSkel ? '#f0f6fc' : '#15191c';\n      ctx.font = 'bold 11.5px \"JetBrains Mono\",Consolas,monospace';\n      ctx.fillText(fm.code + ' ' + fm.name, LEG_X + 50, ly + 13);\n      ctx.fillStyle = isSkel ? '#8b949e' : '#6c6252';\n      ctx.font = '10px \"PingFang SC\",sans-serif';\n      ctx.fillText('旧图: ' + fm.legacyCode, LEG_X + 50, ly + 27);\n      ctx.fillStyle = state.legendJoin ? '#12615a' : '#a3aab0';\n      ctx.fillText(state.legendJoin ? '✓ 已挂接岩性与地质年代' : '— 属性挂接已关闭', LEG_X + 10, ly + 40);\n      ctx.restore();\n    });\n\n    /* 图例下方构造符号说明 */\n    var symY = LEG_Y + 328;\n    ctx.strokeStyle = '#d9d4c8';\n    ctx.beginPath(); ctx.moveTo(LEG_X + 10, symY); ctx.lineTo(LEG_X + LEG_W - 10, symY); ctx.stroke();\n    ctx.fillStyle = isSkel ? '#c9d1d9' : '#424a50';\n    ctx.font = '10.5px \"PingFang SC\",sans-serif';\n    ctx.fillText('▲ 逆冲断层  ┬ 正断层', LEG_X + 12, symY + 20);\n    ctx.fillText('┣ 地层产状  ⊕ 勘探钻孔', LEG_X + 12, symY + 38);\n    ctx.fillStyle = '#12615a';\n    ctx.fillText('点击左图或图例可双向溯源', LEG_X + 12, symY + 62);\n  }\n\n  /* ---------------------------------------------------------\n     3. 辅助分析图 1：四类要素提取精度对比与阈值—F1 响应曲线\n     --------------------------------------------------------- */\n  var f1Svg = document.getElementById('f1Svg');\n\n  function evalClassF1At(th, basePeak, optTh, noise) {\n    var diff = th - optTh;\n    var drop = diff < 0 ? (diff * diff * 95 * (0.7 + noise * 0.8)) : (diff * diff * 145);\n    return Math.max(48, Math.min(99, basePeak - noise * 14 - drop));\n  }\n\n  function renderF1Chart() {\n    var series = [\n      { name: '地层代号 OCR', color: '#6b5aa6', peak: 97.5, opt: 0.58 },\n      { name: '产状符号 (┣)', color: '#2f7d5b', peak: 95.8, opt: 0.60 },\n      { name: '探井钻孔 (⊕)', color: '#3a6ea5', peak: 96.4, opt: 0.56 },\n      { name: '断层骨架线',   color: '#b4483c', peak: 93.6, opt: 0.62 }\n    ];\n    var padL = 40, padR = 18, padT = 26, padB = 28;\n    var cW = 520 - padL - padR, cH = 220 - padT - padB;\n    var xOf = function (t) { return +(padL + ((t - 0.35) / 0.55) * cW).toFixed(1); };\n    var yOf = function (v) { return +(padT + ((100 - v) / 50) * cH).toFixed(1); };\n\n    var html = '';\n    /* 网格线 */\n    [50, 60, 70, 80, 90, 100].forEach(function (yv) {\n      var y = yOf(yv);\n      html += '<line x1=\"' + padL + '\" y1=\"' + y + '\" x2=\"' + (520 - padR) + '\" y2=\"' + y + '\" stroke=\"#e7e3da\" stroke-width=\"1\"/>';\n      html += '<text x=\"' + (padL - 6) + '\" y=\"' + (y + 3.5) + '\" text-anchor=\"end\" font-size=\"10\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">' + yv + '%</text>';\n    });\n    [0.35, 0.50, 0.60, 0.75, 0.90].forEach(function (tv) {\n      var x = xOf(tv);\n      html += '<text x=\"' + x + '\" y=\"' + (220 - 8) + '\" text-anchor=\"middle\" font-size=\"10\" fill=\"#737c83\" font-family=\"ui-monospace,Consolas,monospace\">' + tv.toFixed(2) + '</text>';\n    });\n\n    /* 四条响应曲线 */\n    series.forEach(function (s, idx) {\n      var pts = [];\n      for (var t = 0.35; t <= 0.901; t += 0.025) {\n        pts.push(xOf(t) + ',' + yOf(evalClassF1At(t, s.peak, s.opt, state.noise)));\n      }\n      html += '<polyline fill=\"none\" stroke=\"' + s.color + '\" stroke-width=\"2.2\" points=\"' + pts.join(' ') + '\"/>';\n      var curV = evalClassF1At(state.conf, s.peak, s.opt, state.noise);\n      html += '<circle cx=\"' + xOf(state.conf) + '\" cy=\"' + yOf(curV) + '\" r=\"3.8\" fill=\"#fff\" stroke=\"' + s.color + '\" stroke-width=\"2\"/>';\n\n      /* 顶部图例 + 当前阈值下 F1 读数 */\n      var lx = 14 + idx * 124;\n      html += '<rect x=\"' + lx + '\" y=\"4\" width=\"8\" height=\"8\" rx=\"2\" fill=\"' + s.color + '\"/>';\n      html += '<text x=\"' + (lx + 11) + '\" y=\"11.5\" font-size=\"10.5\" fill=\"#424a50\">' + s.name + ' <tspan font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"600\" fill=\"' + s.color + '\">' + curV.toFixed(0) + '%</tspan></text>';\n    });\n\n    /* 当前置信度阈值竖向指示线 */\n    var cx = xOf(state.conf);\n    html += '<line x1=\"' + cx + '\" y1=\"' + padT + '\" x2=\"' + cx + '\" y2=\"' + (220 - padB) + '\" stroke=\"#12615a\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>';\n    html += '<rect x=\"' + (cx - 28) + '\" y=\"' + (padT + 4) + '\" width=\"56\" height=\"16\" rx=\"4\" fill=\"#12615a\"/>';\n    html += '<text x=\"' + cx + '\" y=\"' + (padT + 15) + '\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">TH=' + state.conf.toFixed(2) + '</text>';\n\n    f1Svg.innerHTML = html;\n  }\n\n  /* ---------------------------------------------------------\n     4. 辅助分析图 2：GIS 结构化属性表 + 要素检查器 + KPI 更新\n     --------------------------------------------------------- */\n  var attrTbody = document.getElementById('attrTbody');\n  var inspTitle = document.getElementById('inspTitle');\n  var inspBadge = document.getElementById('inspBadge');\n  var inspKv = document.getElementById('inspKv');\n  var inspJson = document.getElementById('inspJson');\n\n  function getAllRecords(res) {\n    return [].concat(res.fmResults, res.fltResults, res.dipResults, res.wellResults);\n  }\n\n  function renderAttrTable(res) {\n    var all = getAllRecords(res);\n    document.getElementById('tblSummary').textContent = '共 ' + all.length + ' 条矢量要素记录';\n    var rowsHtml = all.map(function (r) {\n      var isSel = r.id === state.selectedId;\n      var badgeCls = 'ok', badgeTxt = '已闭合';\n      if (!r.detected) {\n        badgeCls = 'bad'; badgeTxt = '低置信度漏检';\n      } else if (r.overMerge) {\n        badgeCls = 'warn'; badgeTxt = '跨距过大粘连';\n      } else if (!r.closed) {\n        badgeCls = 'bad'; badgeTxt = '悬挂断开';\n      } else if (r.conf < state.conf + 0.08) {\n        badgeCls = 'warn'; badgeTxt = '低置信度待审';\n      } else if (r.category === '产状符号' || r.category === '探井钻孔') {\n        badgeCls = 'ok'; badgeTxt = '已检出校准';\n      }\n\n      var sw = r.ref.color ? '<i class=\"swatch\" style=\"background:' + r.ref.color + '\"></i>' : '';\n      return '<tr class=\"clickable' + (isSel ? ' sel' : '') + '\" data-id=\"' + r.id + '\">' +\n        '<td class=\"mono\">' + r.id + '</td>' +\n        '<td>' + r.category + '</td>' +\n        '<td class=\"mono\">' + sw + r.code + '</td>' +\n        '<td>' + r.name + '</td>' +\n        '<td class=\"num\">' + (r.conf * 100).toFixed(0) + '%</td>' +\n        '<td><span class=\"badge ' + badgeCls + '\">' + badgeTxt + '</span></td>' +\n      '</tr>';\n    }).join('');\n    attrTbody.innerHTML = rowsHtml;\n  }\n\n  function renderInspector(res) {\n    var all = getAllRecords(res);\n    var cur = all.find(function (x) { return x.id === state.selectedId; }) || all[3];\n    var ref = cur.ref;\n\n    if (cur.category === '地层多边形') {\n      inspTitle.textContent = '要素检查器 · 已选中：' + ref.code + ' ' + ref.name + '（主图多边形 ⇄ 图例项同步高亮）';\n      inspBadge.className = 'badge ' + (cur.closed ? 'ok' : 'bad');\n      inspBadge.textContent = cur.closed ? '拓扑已闭合 · 图例已挂接' : (cur.overMerge ? '平行界线粘连畸变' : '边界存在悬挂断口');\n      inspKv.innerHTML =\n        '<div><span class=\"k\">要素类型 / ID</span><span class=\"v\">Polygon · ' + cur.id + '</span></div>' +\n        '<div><span class=\"k\">现行代号 / 旧图代号</span><span class=\"v\">' + ref.code + ' ⇄ ' + ref.legacyCode.split(' ')[0] + '</span></div>' +\n        '<div><span class=\"k\">地质年代</span><span class=\"v\">' + (state.legendJoin ? ref.era : '待挂接') + '</span></div>' +\n        '<div><span class=\"k\">岩性描述</span><span class=\"v\">' + (state.legendJoin ? ref.litho.slice(0, 11) + '…' : '未启用图例对齐') + '</span></div>' +\n        '<div><span class=\"k\">边界关联断口</span><span class=\"v\">' + ref.reqGaps.join(', ') + '</span></div>' +\n        '<div><span class=\"k\">OCR 识别置信度</span><span class=\"v\">' + (cur.conf * 100).toFixed(1) + '%</span></div>';\n      inspJson.innerHTML =\n        '{\\n' +\n        '  <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Feature\"</span>, <span class=\"jk\">\"id\"</span>: <span class=\"js\">\"' + cur.id + '\"</span>,\\n' +\n        '  <span class=\"jk\">\"geometry\"</span>: { <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Polygon\"</span>, <span class=\"jk\">\"closed\"</span>: <span class=\"jn\">' + cur.closed + '</span> },\\n' +\n        '  <span class=\"jk\">\"properties\"</span>: {\\n' +\n        '    <span class=\"jk\">\"stratum_code\"</span>: <span class=\"js\">\"' + ref.code + '\"</span>, <span class=\"jk\">\"legacy_code\"</span>: <span class=\"js\">\"' + ref.legacyCode + '\"</span>,\\n' +\n        '    <span class=\"jk\">\"era\"</span>: <span class=\"js\">\"' + (state.legendJoin ? ref.era : '') + '\"</span>, <span class=\"jk\">\"confidence\"</span>: <span class=\"jn\">' + cur.conf + '</span>\\n' +\n        '  }\\n}';\n    } else if (cur.category === '断层线') {\n      inspTitle.textContent = '要素检查器 · 已选中：' + ref.code + '（构造骨架与张量缝合分析）';\n      inspBadge.className = 'badge ' + (cur.closed ? 'ok' : 'warn');\n      inspBadge.textContent = cur.closed ? '断口已全部缝合' : '含未闭合断口';\n      inspKv.innerHTML =\n        '<div><span class=\"k\">要素类型 / ID</span><span class=\"v\">LineString · ' + cur.id + '</span></div>' +\n        '<div><span class=\"k\">断层性质</span><span class=\"v\">' + ref.type + '</span></div>' +\n        '<div><span class=\"k\">产状与运动学</span><span class=\"v\">' + ref.sense.slice(0, 12) + '</span></div>' +\n        '<div><span class=\"k\">压盖断口桥接数</span><span class=\"v\">' + cur.bridgedCnt + ' / ' + cur.totalGaps + ' 处</span></div>' +\n        '<div><span class=\"k\">缝合最大跨距</span><span class=\"v\">' + state.gapPx + ' px</span></div>' +\n        '<div><span class=\"k\">线条提取置信度</span><span class=\"v\">' + (cur.conf * 100).toFixed(1) + '%</span></div>';\n      inspJson.innerHTML =\n        '{\\n' +\n        '  <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Feature\"</span>, <span class=\"jk\">\"id\"</span>: <span class=\"js\">\"' + cur.id + '\"</span>,\\n' +\n        '  <span class=\"jk\">\"geometry\"</span>: { <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"LineString\"</span>, <span class=\"jk\">\"gaps_bridged\"</span>: <span class=\"jn\">' + cur.bridgedCnt + '</span> },\\n' +\n        '  <span class=\"jk\">\"properties\"</span>: {\\n' +\n        '    <span class=\"jk\">\"fault_name\"</span>: <span class=\"js\">\"' + ref.code + '\"</span>, <span class=\"jk\">\"kinematics\"</span>: <span class=\"js\">\"' + ref.type + '\"</span>,\\n' +\n        '    <span class=\"jk\">\"confidence\"</span>: <span class=\"jn\">' + cur.conf + '</span>\\n' +\n        '  }\\n}';\n    } else if (cur.category === '产状符号') {\n      inspTitle.textContent = '要素检查器 · 已选中：产状测点 ' + cur.id + '（旋转框检测 + 倾角 OCR）';\n      inspBadge.className = 'badge ' + (cur.detected ? 'ok' : 'bad');\n      inspBadge.textContent = cur.detected ? '已检出 · 倾角已关联' : '低于阈值未检出';\n      inspKv.innerHTML =\n        '<div><span class=\"k\">要素类型 / ID</span><span class=\"v\">Point · ' + cur.id + '</span></div>' +\n        '<div><span class=\"k\">走向 (Strike)</span><span class=\"v\">N' + ref.strike + '°E</span></div>' +\n        '<div><span class=\"k\">倾向 (Dip Dir)</span><span class=\"v\">' + (ref.strike + 90) + '° (SE)</span></div>' +\n        '<div><span class=\"k\">倾角 (Dip Angle)</span><span class=\"v\">' + ref.dip + '°</span></div>' +\n        '<div><span class=\"k\">所属地层单元</span><span class=\"v\">' + ref.fm + '</span></div>' +\n        '<div><span class=\"k\">检测置信度</span><span class=\"v\">' + (cur.conf * 100).toFixed(1) + '%</span></div>';\n      inspJson.innerHTML =\n        '{\\n' +\n        '  <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Feature\"</span>, <span class=\"jk\">\"id\"</span>: <span class=\"js\">\"' + cur.id + '\"</span>,\\n' +\n        '  <span class=\"jk\">\"geometry\"</span>: { <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Point\"</span>, <span class=\"jk\">\"coordinates\"</span>: [<span class=\"jn\">' + ref.x + '</span>, <span class=\"jn\">' + ref.y + '</span>] },\\n' +\n        '  <span class=\"jk\">\"properties\"</span>: {\\n' +\n        '    <span class=\"jk\">\"strike\"</span>: <span class=\"jn\">' + ref.strike + '</span>, <span class=\"jk\">\"dip_angle\"</span>: <span class=\"jn\">' + ref.dip + '</span>, <span class=\"jk\">\"stratum\"</span>: <span class=\"js\">\"' + ref.fm + '\"</span>,\\n' +\n        '    <span class=\"jk\">\"confidence\"</span>: <span class=\"jn\">' + cur.conf + '</span>\\n' +\n        '  }\\n}';\n    } else {\n      inspTitle.textContent = '要素检查器 · 已选中：探井钻孔 ' + ref.code + '（井位符号 + 井名 OCR）';\n      inspBadge.className = 'badge ' + (cur.detected ? 'ok' : 'bad');\n      inspBadge.textContent = cur.detected ? '井位与注记已对齐' : '低于阈值漏检';\n      inspKv.innerHTML =\n        '<div><span class=\"k\">要素类型 / ID</span><span class=\"v\">Point · ' + cur.id + '</span></div>' +\n        '<div><span class=\"k\">钻孔井号</span><span class=\"v\">' + ref.code + '</span></div>' +\n        '<div><span class=\"k\">完钻井深</span><span class=\"v\">' + ref.depth + '</span></div>' +\n        '<div><span class=\"k\">钻遇油气显示</span><span class=\"v\">' + ref.res + '</span></div>' +\n        '<div><span class=\"k\">开钻层位</span><span class=\"v\">' + ref.fm + '</span></div>' +\n        '<div><span class=\"k\">检测置信度</span><span class=\"v\">' + (cur.conf * 100).toFixed(1) + '%</span></div>';\n      inspJson.innerHTML =\n        '{\\n' +\n        '  <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Feature\"</span>, <span class=\"jk\">\"id\"</span>: <span class=\"js\">\"' + cur.id + '\"</span>,\\n' +\n        '  <span class=\"jk\">\"geometry\"</span>: { <span class=\"jk\">\"type\"</span>: <span class=\"js\">\"Point\"</span>, <span class=\"jk\">\"coordinates\"</span>: [<span class=\"jn\">' + ref.x + '</span>, <span class=\"jn\">' + ref.y + '</span>] },\\n' +\n        '  <span class=\"jk\">\"properties\"</span>: {\\n' +\n        '    <span class=\"jk\">\"well_name\"</span>: <span class=\"js\">\"' + ref.code + '\"</span>, <span class=\"jk\">\"depth\"</span>: <span class=\"js\">\"' + ref.depth + '\"</span>, <span class=\"jk\">\"result\"</span>: <span class=\"js\">\"' + ref.res + '\"</span>\\n' +\n        '  }\\n}';\n    }\n  }\n\n  function updateKPIsAndInsight(res) {\n    var setKpi = function (id, val, desc, level) {\n      var el = document.getElementById(id);\n      el.className = 'kpi ' + level;\n      document.getElementById(id + 'Val').innerHTML = val.toFixed(1) + '<small>%</small>';\n      document.getElementById(id + 'Desc').textContent = desc;\n    };\n\n    setKpi('kpiSym', res.symF1,\n      '检出 ' + res.symTP + '/' + res.symTotal + ' · 伪检 ' + res.falsePos + ' 个',\n      res.symF1 >= 88 ? 'ok' : (res.symF1 >= 75 ? 'warn' : 'bad'));\n\n    setKpi('kpiOcr', res.ocrAcc,\n      state.noise > 0.6 ? '重度泛黄降低上下标识别率' : '上下标语法树校验已激活',\n      res.ocrAcc >= 88 ? 'ok' : (res.ocrAcc >= 75 ? 'warn' : 'bad'));\n\n    setKpi('kpiGap', res.gapRate,\n      res.overMerge ? '跨距过大引发邻线误粘连!' : ('已桥接 ' + res.bridgedCount + '/' + res.totalGaps + ' 处断口'),\n      res.overMerge ? 'warn' : (res.bridgedCount === res.totalGaps ? 'ok' : 'bad'));\n\n    setKpi('kpiPoly', res.polyRate,\n      res.closedFormations + '/5 地层区闭合 · 悬挂点 ' + res.dangles + ' 个',\n      res.polyRate >= 95 ? 'ok' : (res.polyRate >= 60 ? 'warn' : 'bad'));\n\n    /* 顶栏胶囊状态 */\n    var stepNames = [\n      '',\n      '步骤 01 · 版面分割与图纸退化去噪',\n      '步骤 02 · 图例色块—地层代号OCR字典构建',\n      '步骤 03 · 主图符号检测与地层注记识别',\n      '步骤 04 · 断层与界线骨架提取及断线缝合',\n      '步骤 05 · 拓扑多边形构建与属性挂接'\n    ];\n    document.getElementById('stepPill').innerHTML = '<i></i><span>' + stepNames[state.step] + '</span>';\n\n    var topoPill = document.getElementById('topoPill');\n    if (res.polyRate === 100 && !res.overMerge) {\n      topoPill.className = 'pill ok';\n      topoPill.innerHTML = '<i></i><span>拓扑闭合 5/5 · 零悬挂点</span>';\n    } else if (res.overMerge) {\n      topoPill.className = 'pill warn';\n      topoPill.innerHTML = '<i></i><span>警告：跨距过大导致平行界线粘连</span>';\n    } else {\n      topoPill.className = 'pill bad';\n      topoPill.innerHTML = '<i></i><span>拓扑未闭合 ' + res.closedFormations + '/5 · 悬挂点 ' + res.dangles + ' 个</span>';\n    }\n\n    /* 动态机理洞察 */\n    var box = document.getElementById('insightBox');\n    var tag = document.getElementById('insightTag');\n    var txt = document.getElementById('insightText');\n\n    if (state.gapPx < 16) {\n      box.className = 'insight bad';\n      tag.textContent = '断线失效警示';\n      txt.innerHTML = '当前<b>断线拓扑缝合最大跨距为 ' + state.gapPx + ' px</b>（小于文字注记掩膜与折痕造成的 16–21 px 断口宽度）。主图中地层代号 <b>P₂l、T₃x</b> 及产状数字压盖断层线的位置出现 <b>' + res.dangles + ' 个红色悬挂端点 (Dangles)</b>，导致两侧地层无法独立成面（闭合率跌至 <b>' + res.polyRate.toFixed(0) + '%</b>）。请将缝合跨距调至 <b>20–28 px</b> 激活张量场桥接。';\n    } else if (res.overMerge) {\n      box.className = 'insight warn';\n      tag.textContent = '过度粘连警示';\n      txt.innerHTML = '当前<b>断线缝合最大跨距高达 ' + state.gapPx + ' px</b>，超过了中生界薄互层与断层分支间的最小法向间距！算法在桥接文字断口的同时，将相邻平行界线<b>错误横向拉扯粘连</b>（见主图橙红色虚线告警），造成多边形拓扑畸变。建议将跨距回调至 <b>20–26 px</b> 的安全窗口。';\n    } else if (state.noise >= 0.65) {\n      box.className = 'insight warn';\n      tag.textContent = '纸张退化干扰';\n      txt.innerHTML = '当前<b>图纸泛黄与折痕噪声达 ' + state.noise.toFixed(2) + '</b>。历史晒印图的褐斑与贯穿性折痕不仅使上/下标小字符（如 <b>J₂s、P₂l</b>）OCR 准确率下降至 <b>' + res.ocrAcc.toFixed(1) + '%</b>，还拓宽了折痕处的线条断裂跨度。得益于<b>图例栏自校准字典</b>，系统仍可通过色块花纹距离约束纠正单字符误识。';\n    } else {\n      box.className = 'insight';\n      tag.textContent = '机理洞察';\n      txt.innerHTML = '在<b>跨距容差 ' + state.gapPx + ' px、阈值 ' + state.conf.toFixed(2) + '</b> 下，流水线先利用文字检测框生成<b>掩膜保护区</b>，再沿断层骨架端点的<b>走向张量场 (Orientation Tensor)</b> 自动跨过注记与折痕桥接全部 <b>6/6 处断口</b>；同时以右侧<b>本图图例栏</b>为自监督原型，将旧图代号（如 <code>J₂sh</code>）自动对齐至标准地层库（<code>J₂s 沙溪庙组</code>），实现 <b>100% 拓扑多边形闭合与属性挂接</b>。';\n    }\n  }\n\n  function updateAll() {\n    var res = computePipeline();\n    renderMap(res);\n    renderF1Chart();\n    renderAttrTable(res);\n    renderInspector(res);\n    updateKPIsAndInsight(res);\n  }\n\n  /* ---------------------------------------------------------\n     5. 交互事件绑定（点选几何判定、悬停浮动提示、滑杆与预设）\n     --------------------------------------------------------- */\n  function pointInPoly(x, y, poly) {\n    var inside = false;\n    for (var i = 0, j = poly.length - 1; i < poly.length; j = i++) {\n      var xi = poly[i][0], yi = poly[i][1];\n      var xj = poly[j][0], yj = poly[j][1];\n      var intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi + 1e-9) + xi);\n      if (intersect) inside = !inside;\n    }\n    return inside;\n  }\n\n  function distToSegment(px, py, x1, y1, x2, y2) {\n    var dx = x2 - x1, dy = y2 - y1;\n    var l2 = dx * dx + dy * dy;\n    if (l2 === 0) return Math.hypot(px - x1, py - y1);\n    var t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / l2));\n    return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));\n  }\n\n  function hitTest(mx, my) {\n    /* 1) 检查右侧图例点击 */\n    if (mx >= LEG_X && mx <= LEG_X + LEG_W) {\n      for (var i = 0; i < FORMATIONS.length; i++) {\n        var ly = LEG_Y + 52 + i * 54;\n        if (my >= ly - 4 && my <= ly + 44) return { type: '图例项', id: FORMATIONS[i].id, label: FORMATIONS[i].code + ' ' + FORMATIONS[i].name };\n      }\n    }\n    /* 2) 检查探井钻孔 */\n    for (var w = 0; w < WELLS.length; w++) {\n      if (Math.hypot(mx - WELLS[w].x, my - WELLS[w].y) <= 13) {\n        return { type: '探井钻孔', id: WELLS[w].id, label: '⊕ ' + WELLS[w].code + ' (' + WELLS[w].depth + ')' };\n      }\n    }\n    /* 3) 检查产状符号 */\n    for (var d = 0; d < DIPS.length; d++) {\n      if (Math.hypot(mx - DIPS[d].x, my - DIPS[d].y) <= 14) {\n        return { type: '产状符号', id: DIPS[d].id, label: '┣ 走向' + DIPS[d].strike + '° / 倾角' + DIPS[d].dip + '°' };\n      }\n    }\n    /* 4) 检查断层线 */\n    for (var f = 0; f < FAULTS.length; f++) {\n      var pts = FAULTS[f].pts;\n      for (var k = 0; k < pts.length - 1; k++) {\n        if (distToSegment(mx, my, pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1]) <= 8) {\n          return { type: '断层线', id: FAULTS[f].id, label: FAULTS[f].code + ' (' + FAULTS[f].type + ')' };\n        }\n      }\n    }\n    /* 5) 检查主图地层多边形 */\n    for (var p = 0; p < FORMATIONS.length; p++) {\n      if (pointInPoly(mx, my, FORMATIONS[p].poly)) {\n        return { type: '地层单元', id: FORMATIONS[p].id, label: FORMATIONS[p].code + ' ' + FORMATIONS[p].name };\n      }\n    }\n    return null;\n  }\n\n  var tipEl = document.getElementById('mapTip');\n  canvas.addEventListener('mousemove', function (e) {\n    var rect = canvas.getBoundingClientRect();\n    var mx = (e.clientX - rect.left) * (W / rect.width);\n    var my = (e.clientY - rect.top) * (H / rect.height);\n    var hit = hitTest(mx, my);\n    if (hit) {\n      tipEl.className = 'tip on';\n      tipEl.style.left = (e.clientX - rect.left) + 'px';\n      tipEl.style.top = (e.clientY - rect.top) + 'px';\n      tipEl.innerHTML = '<b>' + hit.type + '</b> · ' + hit.label + ' <span style=\"opacity:.75\">[点击查看GeoJSON]</span>';\n    } else {\n      tipEl.className = 'tip';\n    }\n  });\n  canvas.addEventListener('mouseleave', function () { tipEl.className = 'tip'; });\n  canvas.addEventListener('click', function (e) {\n    var rect = canvas.getBoundingClientRect();\n    var mx = (e.clientX - rect.left) * (W / rect.width);\n    var my = (e.clientY - rect.top) * (H / rect.height);\n    var hit = hitTest(mx, my);\n    if (hit) {\n      state.selectedId = hit.id;\n      updateAll();\n    }\n  });\n\n  /* 属性表行点击联动 */\n  attrTbody.addEventListener('click', function (e) {\n    var tr = e.target.closest('tr[data-id]');\n    if (tr) {\n      state.selectedId = tr.getAttribute('data-id');\n      updateAll();\n    }\n  });\n\n  /* 滑杆进度条同步辅助 */\n  function syncRangeStyle(el) {\n    var min = parseFloat(el.min || 0), max = parseFloat(el.max || 100), val = parseFloat(el.value);\n    var pct = ((val - min) / (max - min)) * 100;\n    el.style.setProperty('--p', pct.toFixed(1) + '%');\n  }\n\n  var noiseSlider = document.getElementById('noiseSlider');\n  var confSlider = document.getElementById('confSlider');\n  var gapSlider = document.getElementById('gapSlider');\n\n  [noiseSlider, confSlider, gapSlider].forEach(syncRangeStyle);\n\n  noiseSlider.addEventListener('input', function () {\n    state.noise = parseFloat(this.value);\n    document.getElementById('noiseVal').textContent = state.noise.toFixed(2);\n    syncRangeStyle(this);\n    updateAll();\n  });\n  confSlider.addEventListener('input', function () {\n    state.conf = parseFloat(this.value);\n    document.getElementById('confVal').textContent = state.conf.toFixed(2);\n    syncRangeStyle(this);\n    updateAll();\n  });\n  gapSlider.addEventListener('input', function () {\n    state.gapPx = parseInt(this.value, 10);\n    document.getElementById('gapVal').textContent = state.gapPx + ' px';\n    syncRangeStyle(this);\n    updateAll();\n  });\n\n  /* 复选框绑定 */\n  document.getElementById('chkSymbols').addEventListener('change', function () { state.showSymbols = this.checked; updateAll(); });\n  document.getElementById('chkOcr').addEventListener('change', function () { state.showOcr = this.checked; updateAll(); });\n  document.getElementById('chkLegendJoin').addEventListener('change', function () { state.legendJoin = this.checked; updateAll(); });\n  document.getElementById('chkDangles').addEventListener('change', function () { state.showDangles = this.checked; updateAll(); });\n\n  /* 视图模式切换 */\n  var modeBtns = document.querySelectorAll('#modeSeg button');\n  modeBtns.forEach(function (b) {\n    b.addEventListener('click', function () {\n      modeBtns.forEach(function (x) { x.classList.remove('on'); });\n      b.classList.add('on');\n      state.mode = b.getAttribute('data-mode');\n      updateAll();\n    });\n  });\n\n  /* 顶部 5 步流程步进器 */\n  var stepBtns = document.querySelectorAll('#stepper button');\n  function setStep(s) {\n    state.step = s;\n    stepBtns.forEach(function (b) {\n      var bs = parseInt(b.getAttribute('data-step'), 10);\n      b.classList.toggle('on', bs === s);\n      b.classList.toggle('done', bs < s);\n    });\n    if (s === 4) {\n      state.mode = 'skeleton';\n    } else if (s === 5 && state.mode === 'skeleton') {\n      state.mode = 'overlay';\n    }\n    modeBtns.forEach(function (b) {\n      b.classList.toggle('on', b.getAttribute('data-mode') === state.mode);\n    });\n    updateAll();\n  }\n  stepBtns.forEach(function (b) {\n    b.addEventListener('click', function () {\n      setStep(parseInt(b.getAttribute('data-step'), 10));\n    });\n  });\n\n  /* 预设工况按钮 */\n  function applyParams(noise, conf, gapPx, step) {\n    state.noise = noise; noiseSlider.value = noise; document.getElementById('noiseVal').textContent = noise.toFixed(2); syncRangeStyle(noiseSlider);\n    state.conf = conf; confSlider.value = conf; document.getElementById('confVal').textContent = conf.toFixed(2); syncRangeStyle(confSlider);\n    state.gapPx = gapPx; gapSlider.value = gapPx; document.getElementById('gapVal').textContent = gapPx + ' px'; syncRangeStyle(gapSlider);\n    if (step) setStep(step);\n    else updateAll();\n  }\n\n  document.querySelectorAll('[data-preset]').forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      var p = btn.getAttribute('data-preset');\n      if (p === 'optimal') applyParams(0.25, 0.60, 22, 5);\n      else if (p === 'unbridged') applyParams(0.25, 0.60, 0, 4);\n      else if (p === 'overmerge') applyParams(0.25, 0.60, 40, 4);\n      else if (p === 'heavynoise') applyParams(0.85, 0.65, 22, 3);\n    });\n  });\n\n  document.getElementById('btnReset').addEventListener('click', function () {\n    state.showSymbols = true; document.getElementById('chkSymbols').checked = true;\n    state.showOcr = true; document.getElementById('chkOcr').checked = true;\n    state.legendJoin = true; document.getElementById('chkLegendJoin').checked = true;\n    state.showDangles = true; document.getElementById('chkDangles').checked = true;\n    state.mode = 'overlay';\n    applyParams(0.25, 0.60, 22, 5);\n  });\n\n  /* 步进播放演示 */\n  var btnPlay = document.getElementById('btnPlay');\n  btnPlay.addEventListener('click', function () {\n    if (state.playTimer) {\n      clearInterval(state.playTimer);\n      state.playTimer = null;\n      btnPlay.textContent = '▶ 步进演示';\n      return;\n    }\n    var cur = 1;\n    setStep(cur);\n    btnPlay.textContent = '⏸ 演示中...';\n    state.playTimer = setInterval(function () {\n      cur++;\n      if (cur > 5) {\n        clearInterval(state.playTimer);\n        state.playTimer = null;\n        btnPlay.textContent = '▶ 步进演示';\n        return;\n      }\n      setStep(cur);\n    }, 1100);\n  });\n\n  updateAll();\n})();\n","enc":"text","size":52805}]};